// 每句只引用一句台词作日语学习说明，版权归原作者所有。
window.DAILY_LINES = [{"id":1,"jp":"ポニョ、宗介好き！","ruby":"ポニョ、<ruby>宗介<rt>そうすけ</rt></ruby><ruby>好<rt>す</rt></ruby>き！","romaji":"Ponyo, Sōsuke suki!","zh":"波妞喜欢宗介！","level":"N5","point":"「好き」表示“喜欢”，完整说法是「AはBが好き」，口语里常把「は」「が」都省略。想表达喜好时直接说「〇〇好き！」就很自然。","example":"私はラーメンが好きです。（我喜欢拉面。）","work":"崖の上のポニョ","workZh":"悬崖上的金鱼姬","ep":"劇場版","speaker":"ポニョ","verify":true,"chunks":["ポニョ、","宗介","好き！"]},{"id":2,"jp":"あなた、トトロっていうのね！","ruby":"あなた、トトロっていうのね！","romaji":"Anata, Totoro tte iu no ne!","zh":"你叫龙猫啊！","level":"N5","point":"「～っていう」是「～という（叫作……）」的口语形式，常用来问或确认名字。句尾「のね」表示恍然大悟、确认。","example":"この花、何っていうの？（这花叫什么？）","work":"となりのトトロ","workZh":"龙猫","ep":"劇場版","speaker":"メイ","verify":true,"chunks":["あなた、","トトロって","いうのね！"]},{"id":3,"jp":"私、魔女のキキです。","ruby":"<ruby>私<rt>わたし</rt></ruby>、<ruby>魔女<rt>まじょ</rt></ruby>のキキです。","romaji":"Watashi, majo no Kiki desu.","zh":"我是魔女琪琪。","level":"N5","point":"「AのBです」是最基本的自我介绍句型：「の」连接名词表示“……的”。口语中「私は」的「は」常被省略。","example":"私、大学生の陳です。（我是大学生，姓陈。）","work":"魔女の宅急便","workZh":"魔女宅急便","ep":"劇場版","speaker":"キキ","verify":true,"chunks":["私、","魔女の","キキです。"]},{"id":4,"jp":"元気100倍、アンパンマン！","ruby":"<ruby>元気<rt>げんき</rt></ruby>100<ruby>倍<rt>ばい</rt></ruby>、アンパンマン！","romaji":"Genki hyaku-bai, Anpanman!","zh":"元气100倍，面包超人！","level":"N5","point":"「元気」表示有精神、身体好。日常打招呼最常用「お元気ですか」（您好吗）和朋友间的「元気？」。","example":"久しぶり！元気？（好久不见！还好吗？）","work":"それいけ!アンパンマン","workZh":"面包超人","ep":"","speaker":"アンパンマン","verify":true,"chunks":["元気","100倍、","アンパンマン！"]},{"id":5,"jp":"ピカチュウ、君に決めた！","ruby":"ピカチュウ、<ruby>君<rt>きみ</rt></ruby>に<ruby>決<rt>き</rt></ruby>めた！","romaji":"Pikachū, kimi ni kimeta!","zh":"皮卡丘，就决定是你了！","level":"N5","point":"「～に決める」表示“决定选……”，过去式「決めた」表示已经拿定主意。点菜、挑东西时都能用。","example":"今日のランチはカレーに決めた！（今天午饭就定咖喱了！）","work":"ポケットモンスター","workZh":"宝可梦","ep":"","speaker":"サトシ","verify":true,"chunks":["ピカチュウ、","君に","決めた！"]},{"id":6,"jp":"オッス、オラ悟空！","ruby":"オッス、オラ<ruby>悟空<rt>ごくう</rt></ruby>！","romaji":"Ossu, ora Gokū!","zh":"哟！我是悟空！","level":"N5","point":"「オッス」是男生之间很随便的打招呼；「オラ」是方言里的“我”（标准语是「おれ」「わたし」）。自我介绍最简单就是「（私は）＋名字」。","example":"こんにちは、私は李です。（你好，我是小李。）","work":"ドラゴンボール","workZh":"龙珠","ep":"","speaker":"孫悟空","verify":true,"chunks":["オッス、","オラ","悟空！"]},{"id":7,"jp":"あんたバカァ？","ruby":"あんたバカァ？","romaji":"Anta bakā?","zh":"你是笨蛋吗？","level":"N5","point":"日语口语疑问句可以不加「か」，只把句尾语调上扬即可。注意「あんた」「バカ」语气很冲，只适合非常熟的朋友开玩笑。","example":"明日、来る？（明天来吗？）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"","speaker":"惣流・アスカ・ラングレー","verify":true,"chunks":["あんた","バカ","ァ？"]},{"id":8,"jp":"うちの子になる？","ruby":"うちの<ruby>子<rt>こ</rt></ruby>になる？","romaji":"Uchi no ko ni naru?","zh":"要不要做我家的孩子？","level":"N5","point":"「～になる」表示“变成、成为……”。「うち」口语里指“我家”。领养宠物、邀请别人加入时都能用这个句型。","example":"将来、先生になりたいです。（将来想当老师。）","work":"すずめの戸締まり","workZh":"铃芽之旅","ep":"劇場版","speaker":"岩戸鈴芽","verify":true,"chunks":["うちの","子に","なる？"]},{"id":10,"jp":"君の、名前は。","ruby":"<ruby>君<rt>きみ</rt></ruby>の、<ruby>名前<rt>なまえ</rt></ruby>は。","romaji":"Kimi no, namae wa.","zh":"你的名字是？","level":"N5","point":"「～は？」把问句后半省略，只留话题，用升调就是在提问。问名字时礼貌说法是「お名前は？」。","example":"すみません、お名前は？（不好意思，请问您贵姓？）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"立花瀧・宮水三葉","verify":true,"chunks":["君の、","名前","は。"]},{"id":11,"jp":"ねぇ、今から晴れるよ。","ruby":"ねぇ、<ruby>今<rt>いま</rt></ruby>から<ruby>晴<rt>は</rt></ruby>れるよ。","romaji":"Nē, ima kara hareru yo.","zh":"呐，马上就要放晴了哦。","level":"N5","point":"「今から」表示“从现在起、马上”；句尾「よ」用来告诉对方他不知道的信息。","example":"今から行くよ！（我现在就过去！）","work":"天気の子","workZh":"天气之子","ep":"劇場版","speaker":"天野陽菜","verify":true,"chunks":["ねぇ、","今から","晴れるよ。"]},{"id":12,"jp":"未来で待ってる。","ruby":"<ruby>未来<rt>みらい</rt></ruby>で<ruby>待<rt>ま</rt></ruby>ってる。","romaji":"Mirai de matteru.","zh":"我在未来等你。","level":"N5","point":"「待ってる」是「待っている」的口语缩略，「～ている」表示动作持续进行。「で」表示动作发生的地点。","example":"駅の前で待ってるね。（我在车站前等你哦。）","work":"時をかける少女","workZh":"穿越时空的少女","ep":"劇場版（2006年）","speaker":"間宮千昭","verify":true,"chunks":["未来","で","待ってる。"]},{"id":13,"jp":"アーニャ、ピーナッツがすき。","ruby":"アーニャ、ピーナッツがすき。","romaji":"Ānya, pīnattsu ga suki.","zh":"阿尼亚喜欢花生。","level":"N5","point":"小孩子常用自己的名字代替「私」。「Bがすき」中喜欢的对象用「が」标出，这是初学者最容易错的地方。","example":"妹はいちごがすきです。（妹妹喜欢草莓。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ・フォージャー","verify":true,"chunks":["アーニャ、","ピーナッツが","すき。"]},{"id":14,"jp":"おまえのものはおれのもの、おれのものもおれのもの。","ruby":"おまえのものはおれのもの、おれのものもおれのもの。","romaji":"Omae no mono wa ore no mono, ore no mono mo ore no mono.","zh":"你的东西是我的，我的东西也是我的。","level":"N5","point":"对比「は」和「も」：「は」提出话题，「も」表示“也”。这句话是有名的“霸道发言”，日常常拿来开玩笑。","example":"私はコーヒーが好きです。弟もコーヒーが好きです。（我喜欢咖啡，弟弟也喜欢。）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"ジャイアン（剛田武）","verify":true,"chunks":["おまえのものは","おれのもの、","おれのものも","おれのもの。"]},{"id":15,"jp":"見た目は子供、頭脳は大人。","ruby":"<ruby>見<rt>み</rt></ruby>た<ruby>目<rt>め</rt></ruby>は<ruby>子供<rt>こども</rt></ruby>、<ruby>頭脳<rt>ずのう</rt></ruby>は<ruby>大人<rt>おとな</rt></ruby>。","romaji":"Mitame wa kodomo, zunō wa otona.","zh":"外表是小孩，头脑却是大人。","level":"N5","point":"「AはB、CはD」用两个「は」形成对比，省略了「です／だ」。描述人的两面时非常好用。","example":"兄は医者、弟は先生。（哥哥是医生，弟弟是老师。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"江戸川コナン","verify":true,"chunks":["見た目は","子供、","頭脳は","大人。"]},{"id":16,"jp":"あれれ～？おかしいぞ～。","ruby":"あれれ～？おかしいぞ～。","romaji":"Arere~? Okashii zo~.","zh":"咦？好奇怪哦～","level":"N5","point":"「おかしい」除了“好笑”，更常用的意思是“奇怪、不对劲”。「あれ？」是发现异常时的口头禅。","example":"あれ？このパソコン、おかしいな。（咦？这台电脑有点不对劲。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"江戸川コナン","verify":true,"chunks":["あれれ～？","おかしい","ぞ～。"]},{"id":17,"jp":"アムロ、行きまーす！","ruby":"アムロ、<ruby>行<rt>い</rt></ruby>きまーす！","romaji":"Amuro, ikimāsu!","zh":"阿姆罗，出击！","level":"N5","point":"「ます」形不只是礼貌，也可以用来宣告自己马上要做的事。出门、出发、开始做事时都可以说「行きます！」。","example":"じゃあ、そろそろ行きます！（那我差不多该走了！）","work":"機動戦士ガンダム","workZh":"机动战士高达","ep":"","speaker":"アムロ・レイ","verify":true,"chunks":["アムロ、","行き","まーす！"]},{"id":18,"jp":"オラ、野原しんのすけ。5歳だゾ！","ruby":"オラ、<ruby>野原<rt>のはら</rt></ruby>しんのすけ。5<ruby>歳<rt>さい</rt></ruby>だゾ！","romaji":"Ora, Nohara Shinnosuke. Go-sai da zo!","zh":"我是野原新之助，5岁！","level":"N5","point":"年龄用「数字＋歳（さい）」表达。句尾「ぞ」语气强调，是男孩子气的说法，一般自我介绍用「～です」即可。","example":"妹は十五歳です。（妹妹十五岁。）","work":"クレヨンしんちゃん","workZh":"蜡笔小新","ep":"","speaker":"野原しんのすけ","verify":true,"chunks":["オラ、","野原しんのすけ。","5歳","だゾ！"]},{"id":19,"jp":"安西先生…バスケがしたいです…","ruby":"<ruby>安西<rt>あんざい</rt></ruby><ruby>先生<rt>せんせい</rt></ruby>…バスケがしたいです…","romaji":"Anzai-sensei... basuke ga shitai desu...","zh":"安西教练……我想打篮球……","level":"N5","point":"「动词ます形去ます＋たい」表示“想做……”，想做的对象常用「が」或「を」。表达愿望时最基本的句型。","example":"週末は映画が見たいです。（周末想看电影。）","work":"SLAM DUNK","workZh":"灌篮高手","ep":"","speaker":"三井寿","verify":true,"chunks":["安西先生…","バスケが","したいです…"]},{"id":20,"jp":"真実はいつもひとつ！","ruby":"<ruby>真実<rt>しんじつ</rt></ruby>はいつもひとつ！","romaji":"Shinjitsu wa itsumo hitotsu!","zh":"真相永远只有一个！","level":"N4","point":"「いつも」表示“总是、一直”，放在谓语前面。描述习惯时非常常用。","example":"父はいつも朝六時に起きます。（爸爸总是早上六点起床。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"江戸川コナン","verify":true,"chunks":["真実は","いつも","ひとつ！"]},{"id":21,"jp":"しょうがないなあ、のび太くんは。","ruby":"しょうがないなあ、のび<ruby>太<rt>た</rt></ruby>くんは。","romaji":"Shōganai nā, Nobita-kun wa.","zh":"真拿你没办法啊，大雄。","level":"N4","point":"「しょうがない」意思是“没办法、只好这样”，带点无奈又宠溺的语气。答应别人的小请求时常说。","example":"雨か…しょうがない、家で映画を見よう。（下雨了啊……没办法，在家看电影吧。）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"ドラえもん","verify":true,"chunks":["しょうがない","なあ、","のび太くんは。"]},{"id":22,"jp":"ドラえもーん、なんとかしてよ～！","ruby":"ドラえもーん、なんとかしてよ～！","romaji":"Doraemōn, nantoka shite yo~!","zh":"哆啦A梦，快想想办法嘛～！","level":"N4","point":"「なんとかする」意为“想办法解决”；「～てよ」是撒娇或催促的请求语气，比「～てください」随便。","example":"パソコンが動かない…なんとかしてよ！（电脑动不了了……帮我想想办法嘛！）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"野比のび太","verify":true,"chunks":["ドラえもーん、","なんとか","してよ～！"]},{"id":23,"jp":"ただの人間には興味ありません。","ruby":"ただの<ruby>人間<rt>にんげん</rt></ruby>には<ruby>興味<rt>きょうみ</rt></ruby>ありません。","romaji":"Tada no ningen ni wa kyōmi arimasen.","zh":"我对普通人类没有兴趣。","level":"N4","point":"「～に興味がある／ない」表示“对……有／没有兴趣”，口语中「が」常省略。聊爱好时很好用。","example":"私は日本の歴史に興味があります。（我对日本历史有兴趣。）","work":"涼宮ハルヒの憂鬱","workZh":"凉宫春日的忧郁","ep":"","speaker":"涼宮ハルヒ","verify":true,"chunks":["ただの","人間には","興味","ありません。"]},{"id":24,"jp":"大丈夫、僕最強だから。","ruby":"<ruby>大丈夫<rt>だいじょうぶ</rt></ruby>、<ruby>僕<rt>ぼく</rt></ruby><ruby>最強<rt>さいきょう</rt></ruby>だから。","romaji":"Daijōbu, boku saikyō dakara.","zh":"放心，因为我是最强的。","level":"N4","point":"「～から」表示原因，口语里常把理由放到句末补充说明。安慰别人时可以说「大丈夫、～から」。","example":"大丈夫、まだ時間あるから。（没事，还有时间呢。）","work":"呪術廻戦","workZh":"咒术回战","ep":"","speaker":"五条悟","verify":true,"chunks":["大丈夫、","僕","最強","だから。"]},{"id":25,"jp":"海賊王に、おれはなる！","ruby":"<ruby>海賊王<rt>かいぞくおう</rt></ruby>に、おれはなる！","romaji":"Kaizoku-ō ni, ore wa naru!","zh":"我是要成为海贼王的男人！（我要成为海贼王！）","level":"N4","point":"正常语序是「おれは海賊王になる」，把目标「海賊王に」提前是为了强调。「～になる」表示成为。","example":"医者に、私はなる！（我要当医生！——模仿说法）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"モンキー・D・ルフィ","verify":true,"chunks":["海賊王に、","おれは","なる！"]},{"id":26,"jp":"私も一緒に海へ連れてって！","ruby":"<ruby>私<rt>わたし</rt></ruby>も<ruby>一緒<rt>いっしょ</rt></ruby>に<ruby>海<rt>うみ</rt></ruby>へ<ruby>連<rt>つ</rt></ruby>れてって！","romaji":"Watashi mo issho ni umi e tsuretette!","zh":"也带我一起去大海吧！","level":"N4","point":"「連れてって」是「連れていって（ください）」的口语缩略，意思是“带我去”。熟人之间请求时省略「ください」。","example":"今度、おいしい店に連れてって！（下次带我去好吃的店嘛！）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"ニコ・ロビン","verify":true,"chunks":["私も","一緒に","海へ","連れてって！"]},{"id":27,"jp":"愛してくれて…ありがとう！","ruby":"<ruby>愛<rt>あい</rt></ruby>してくれて…ありがとう！","romaji":"Aishite kurete... arigatō!","zh":"谢谢你们……爱着我！","level":"N4","point":"「～てくれて、ありがとう」表示“谢谢你为我做了……”，比单说「ありがとう」更具体真诚。","example":"手伝ってくれて、ありがとう。（谢谢你帮我。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"ポートガス・D・エース","verify":true,"chunks":["愛して","くれて…","ありがとう！"]},{"id":28,"jp":"逃げちゃダメだ。","ruby":"<ruby>逃<rt>に</rt></ruby>げちゃダメだ。","romaji":"Nigecha dame da.","zh":"不能逃避。","level":"N4","point":"「～ちゃダメ」是「～てはダメ（不可以……）」的口语缩略，用于禁止或给自己打气。","example":"ここで寝ちゃダメだよ。（不能在这里睡哦。）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"第1話","speaker":"碇シンジ","verify":true,"chunks":["逃げちゃ","ダメ","だ。"]},{"id":29,"jp":"笑えばいいと思うよ。","ruby":"<ruby>笑<rt>わら</rt></ruby>えばいいと<ruby>思<rt>おも</rt></ruby>うよ。","romaji":"Waraeba ii to omou yo.","zh":"我想，笑一笑就好了。","level":"N4","point":"「～ばいい」表示“只要……就好”，「～と思う」表示委婉的看法。合起来是给建议的温柔说法。","example":"わからないときは、先生に聞けばいいと思うよ。（不懂的时候问老师就好啦。）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"第6話","speaker":"碇シンジ","verify":true,"chunks":["笑えば","いいと","思うよ。"]},{"id":30,"jp":"あきらめたらそこで試合終了ですよ。","ruby":"あきらめたらそこで<ruby>試合<rt>しあい</rt></ruby><ruby>終了<rt>しゅうりょう</rt></ruby>ですよ。","romaji":"Akirametara soko de shiai shūryō desu yo.","zh":"一旦放弃，比赛就在那一刻结束了。","level":"N4","point":"「～たら」表示假设条件“如果……的话”。鼓励别人坚持时这句话在日本几乎人人都知道。","example":"疲れたら、少し休んでね。（累了的话就休息一下哦。）","work":"SLAM DUNK","workZh":"灌篮高手","ep":"","speaker":"安西光義","verify":true,"chunks":["あきらめたら","そこで","試合終了","ですよ。"]},{"id":31,"jp":"左手は添えるだけ。","ruby":"<ruby>左手<rt>ひだりて</rt></ruby>は<ruby>添<rt>そ</rt></ruby>えるだけ。","romaji":"Hidarite wa soeru dake.","zh":"左手只是辅助而已。","level":"N4","point":"「～だけ」表示“只、仅仅”，接在动词原形或名词后面。日常说“只要……就行”时很常用。","example":"あとはボタンを押すだけです。（接下来只要按下按钮就行。）","work":"SLAM DUNK","workZh":"灌篮高手","ep":"","speaker":"桜木花道","verify":true,"chunks":["左手は","添える","だけ。"]},{"id":32,"jp":"来世は東京のイケメン男子にしてくださーい！","ruby":"<ruby>来世<rt>らいせ</rt></ruby>は<ruby>東京<rt>とうきょう</rt></ruby>のイケメン<ruby>男子<rt>だんし</rt></ruby>にしてくださーい！","romaji":"Raise wa Tōkyō no ikemen danshi ni shite kudasāi!","zh":"下辈子请让我当东京的帅哥吧！","level":"N4","point":"「Aを／はBにしてください」表示“请把A变成／定为B”。点餐、改设置时都能用。","example":"飲み物はコーヒーにしてください。（饮料请给我咖啡。）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"宮水三葉","verify":true,"chunks":["来世は","東京の","イケメン男子に","してくださーい！"]},{"id":33,"jp":"ここで働かせてください！","ruby":"ここで<ruby>働<rt>はたら</rt></ruby>かせてください！","romaji":"Koko de hatarakasete kudasai!","zh":"请让我在这里工作！","level":"N4","point":"「使役形＋てください」＝「请让我……」，是很有礼貌地请求许可的说法。","example":"少し考えさせてください。（请让我考虑一下。）","work":"千と千尋の神隠し","workZh":"千与千寻","ep":"劇場版","speaker":"荻野千尋","verify":true,"chunks":["ここで","働かせて","ください！"]},{"id":34,"jp":"40秒で支度しな！","ruby":"40<ruby>秒<rt>びょう</rt></ruby>で<ruby>支度<rt>したく</rt></ruby>しな！","romaji":"Yonjū-byō de shitaku shina!","zh":"给你40秒准备！","level":"N4","point":"「で」可以表示时间期限“在……之内”。「～しな」是「しなさい」的随便说法，语气强硬，多用于长辈对晚辈。","example":"10分で準備して！（10分钟内准备好！）","work":"天空の城ラピュタ","workZh":"天空之城","ep":"劇場版","speaker":"ドーラ","verify":true,"chunks":["40秒で","支度","しな！"]},{"id":35,"jp":"生きろ。そなたは美しい。","ruby":"<ruby>生<rt>い</rt></ruby>きろ。そなたは<ruby>美<rt>うつく</rt></ruby>しい。","romaji":"Ikiro. Sonata wa utsukushii.","zh":"活下去。你很美。","level":"N4","point":"「生きろ」是「生きる」的命令形，语气非常强烈；「そなた」是古语的“你”。日常请求一般用「～て」或「～てください」。","example":"もっとゆっくり食べて。（吃慢一点。）","work":"もののけ姫","workZh":"幽灵公主","ep":"劇場版","speaker":"アシタカ","verify":true,"chunks":["生きろ。","そなたは","美しい。"]},{"id":36,"jp":"黙れ小僧！","ruby":"<ruby>黙<rt>だま</rt></ruby>れ<ruby>小僧<rt>こぞう</rt></ruby>！","romaji":"Damare kozō!","zh":"住口，小子！","level":"N4","point":"「黙れ」是「黙る（沉默）」的命令形，非常粗鲁。日常想让别人安静，请说「静かにしてください」。","example":"図書館では静かにしてください。（图书馆里请保持安静。）","work":"もののけ姫","workZh":"幽灵公主","ep":"劇場版","speaker":"モロ","verify":true,"chunks":["黙","れ","小僧！"]},{"id":37,"jp":"青空よりも、俺は陽菜がいい！","ruby":"<ruby>青空<rt>あおぞら</rt></ruby>よりも、<ruby>俺<rt>おれ</rt></ruby>は<ruby>陽菜<rt>ひな</rt></ruby>がいい！","romaji":"Aozora yori mo, ore wa Hina ga ii!","zh":"比起蓝天，我更想要阳菜！","level":"N4","point":"「AよりBがいい」表示“比起A，B更好／我更想要B”。做选择、表达偏好时非常实用。","example":"パンよりご飯がいいです。（比起面包，我更想吃米饭。）","work":"天気の子","workZh":"天气之子","ep":"劇場版","speaker":"森嶋帆高","verify":true,"chunks":["青空よりも、","俺は","陽菜が","いい！"]},{"id":38,"jp":"頑張れ炭治郎頑張れ！","ruby":"<ruby>頑張<rt>がんば</rt></ruby>れ<ruby>炭治郎<rt>たんじろう</rt></ruby><ruby>頑張<rt>がんば</rt></ruby>れ！","romaji":"Ganbare Tanjirō ganbare!","zh":"加油炭治郎，加油！","level":"N4","point":"「頑張れ」是命令形，用来给人（或自己）打气；对朋友想说得更温柔时用「頑張って」，对长辈用「頑張ってください」。","example":"明日の試験、頑張って！（明天的考试加油！）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"竈門炭治郎","verify":true,"chunks":["頑張れ","炭治郎","頑張れ！"]},{"id":39,"jp":"この世界は残酷だ…そして…とても美しい。","ruby":"この<ruby>世界<rt>せかい</rt></ruby>は<ruby>残酷<rt>ざんこく</rt></ruby>だ…そして…とても<ruby>美<rt>うつく</rt></ruby>しい。","romaji":"Kono sekai wa zankoku da... soshite... totemo utsukushii.","zh":"这个世界很残酷……但也……非常美丽。","level":"N4","point":"「そして」表示“而且、然后”，用来连接两个句子。写日记或叙述事情经过时经常用到。","example":"朝ご飯を食べました。そして、学校へ行きました。（吃了早饭，然后去了学校。）","work":"進撃の巨人","workZh":"进击的巨人","ep":"","speaker":"ミカサ・アッカーマン","verify":true,"chunks":["この世界は","残酷だ…","そして…","とても","美しい。"]},{"id":41,"jp":"俺がいれば、お前は最強だ！","ruby":"<ruby>俺<rt>おれ</rt></ruby>がいれば、お<ruby>前<rt>まえ</rt></ruby>は<ruby>最強<rt>さいきょう</rt></ruby>だ！","romaji":"Ore ga ireba, omae wa saikyō da!","zh":"只要有我在，你就是最强的！","level":"N4","point":"「～ば」是条件形，表示“只要……就……”。「いれば」来自「いる（在）」。鼓励朋友时很有力量。","example":"練習すれば、上手になるよ。（只要练习，就会变厉害哦。）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"影山飛雄","verify":true,"chunks":["俺が","いれば、","お前は","最強だ！"]},{"id":42,"jp":"「愛してる」を、知りたいのです。","ruby":"「<ruby>愛<rt>あい</rt></ruby>してる」を、<ruby>知<rt>し</rt></ruby>りたいのです。","romaji":"\"Aishiteru\" o, shiritai no desu.","zh":"我想知道“我爱你”的意思。","level":"N4","point":"「～のです（～んです）」用于说明理由或表达自己的心情，比单说「知りたいです」更有“我是认真的”的感觉。","example":"日本の文化をもっと知りたいんです。（我是真的想多了解日本文化。）","work":"ヴァイオレット・エヴァーガーデン","workZh":"紫罗兰永恒花园","ep":"","speaker":"ヴァイオレット・エヴァーガーデン","verify":true,"chunks":["「愛してる」を、","知りたい","のです。"]},{"id":43,"jp":"立って歩け。前へ進め。","ruby":"<ruby>立<rt>た</rt></ruby>って<ruby>歩<rt>ある</rt></ruby>け。<ruby>前<rt>まえ</rt></ruby>へ<ruby>進<rt>すす</rt></ruby>め。","romaji":"Tatte aruke. Mae e susume.","zh":"站起来走下去，向前进。","level":"N4","point":"「立って歩け」中「て形」连接两个动作（站起来→走）。「歩け」「進め」是命令形，日常鼓励可改成「前へ進もう」。","example":"顔を洗って、歯をみがいて、学校へ行く。（洗脸、刷牙，然后去学校。）","work":"鋼の錬金術師","workZh":"钢之炼金术师","ep":"","speaker":"エドワード・エルリック","verify":true,"chunks":["立って","歩け。","前へ","進め。"]},{"id":44,"jp":"僕と契約して、魔法少女になってよ！","ruby":"<ruby>僕<rt>ぼく</rt></ruby>と<ruby>契約<rt>けいやく</rt></ruby>して、<ruby>魔法少女<rt>まほうしょうじょ</rt></ruby>になってよ！","romaji":"Boku to keiyaku shite, mahō shōjo ni natte yo!","zh":"和我签订契约，成为魔法少女吧！","level":"N4","point":"「～てよ」是比较随便的请求，带一点撒娇或催促。对朋友可以用，对上级请用「～てください」。","example":"ちょっと手伝ってよ！（帮我一下嘛！）","work":"魔法少女まどか☆マギカ","workZh":"魔法少女小圆","ep":"","speaker":"キュゥべえ","verify":true,"chunks":["僕と","契約して、","魔法少女に","なってよ！"]},{"id":45,"jp":"やなやつ！やなやつ！やなやつ！","ruby":"やなやつ！やなやつ！やなやつ！","romaji":"Yana yatsu! Yana yatsu! Yana yatsu!","zh":"讨厌的家伙！讨厌的家伙！讨厌的家伙！","level":"N4","point":"「やな」是「嫌（いや）な」的口语缩略，「やつ」是对人的随便说法（家伙）。「嫌なやつ」＝讨厌的人，生气时口语里常说成「やなやつ」。","example":"あの人、本当に嫌な人だね。（那个人真讨厌啊。）","work":"耳をすませば","workZh":"侧耳倾听","ep":"","speaker":"月島雫","verify":true,"chunks":["やな","やつ！","やなやつ！やなやつ！"]},{"id":46,"jp":"贅沢な名だねぇ。","ruby":"<ruby>贅沢<rt>ぜいたく</rt></ruby>な<ruby>名<rt>な</rt></ruby>だねぇ。","romaji":"Zeitaku na na da nē.","zh":"真是个奢侈的名字啊。","level":"N3","point":"「な形容词＋な＋名词」修饰名词，如「贅沢な名」。句尾「ねぇ」表示感叹，带点讽刺或感慨。","example":"きれいな部屋だね。（真是个干净的房间呢。）","work":"千と千尋の神隠し","workZh":"千与千寻","ep":"劇場版","speaker":"湯婆婆","verify":true,"chunks":["贅沢な","名","だねぇ。"]},{"id":47,"jp":"ねぇ、秒速5センチなんだって。","ruby":"ねぇ、<ruby>秒速<rt>びょうそく</rt></ruby>5センチなんだって。","romaji":"Nē, byōsoku go-senchi nan datte.","zh":"呐，听说是每秒5厘米哦。","level":"N3","point":"「～んだって」表示传闻“听说……”，把别人那里听来的信息转述给朋友时非常常用。","example":"明日、雨なんだって。（听说明天下雨。）","work":"秒速5センチメートル","workZh":"秒速5厘米","ep":"劇場版","speaker":"篠原明里","verify":true,"chunks":["ねぇ、","秒速5センチ","なんだって。"]},{"id":48,"jp":"見ろ！人がゴミのようだ！","ruby":"<ruby>見<rt>み</rt></ruby>ろ！<ruby>人<rt>ひと</rt></ruby>がゴミのようだ！","romaji":"Miro! Hito ga gomi no yō da!","zh":"看啊！人就像垃圾一样！","level":"N3","point":"「名词＋のようだ」表示比喻“像……一样”。日常描述可以说「夢のようだ」（像做梦一样）。","example":"今日は夏のように暑いですね。（今天热得像夏天一样呢。）","work":"天空の城ラピュタ","workZh":"天空之城","ep":"劇場版","speaker":"ムスカ","verify":true,"chunks":["見ろ！","人が","ゴミの","ようだ！"]},{"id":49,"jp":"飛ばねぇ豚はただの豚だ。","ruby":"<ruby>飛<rt>と</rt></ruby>ばねぇ<ruby>豚<rt>ぶた</rt></ruby>はただの<ruby>豚<rt>ぶた</rt></ruby>だ。","romaji":"Tobanē buta wa tada no buta da.","zh":"不会飞的猪，就只是普通的猪。","level":"N3","point":"「～ねぇ」是「～ない」的粗犷男性口语；「ただの～」表示“只是普通的……”。","example":"これはただの風邪だから、心配しないで。（这只是普通感冒，别担心。）","work":"紅の豚","workZh":"红猪","ep":"劇場版","speaker":"ポルコ・ロッソ","verify":true,"chunks":["飛ばねぇ","豚は","ただの","豚だ。"]},{"id":50,"jp":"仲間を大切にしない奴は、それ以上のクズだ。","ruby":"<ruby>仲間<rt>なかま</rt></ruby>を<ruby>大切<rt>たいせつ</rt></ruby>にしない<ruby>奴<rt>やつ</rt></ruby>は、それ<ruby>以上<rt>いじょう</rt></ruby>のクズだ。","romaji":"Nakama o taisetsu ni shinai yatsu wa, sore ijō no kuzu da.","zh":"不珍惜同伴的家伙，是比那更差劲的废物。","level":"N3","point":"「～を大切にする」表示“珍惜、重视……”，可以用于人、物、时间。注意「奴」「クズ」是粗话，不要对人直接用。","example":"家族を大切にしてください。（请珍惜家人。）","work":"NARUTO -ナルト-","workZh":"火影忍者","ep":"","speaker":"はたけカカシ","verify":true,"chunks":["仲間を","大切にしない","奴は、","それ以上の","クズだ。"]},{"id":51,"jp":"心を燃やせ。","ruby":"<ruby>心<rt>こころ</rt></ruby>を<ruby>燃<rt>も</rt></ruby>やせ。","romaji":"Kokoro o moyase.","zh":"燃烧你的心吧。","level":"N3","point":"「燃やす」是他动词（让……燃烧），对应自动词「燃える」（燃烧）。日语里很多动词都有这样成对的自/他动词。","example":"ゴミを燃やしてはいけません。（不可以焚烧垃圾。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"劇場版「無限列車編」","speaker":"煉獄杏寿郎","verify":true,"chunks":["心","を","燃やせ。"]},{"id":52,"jp":"駆逐してやる！この世から…一匹残らず！","ruby":"<ruby>駆逐<rt>くちく</rt></ruby>してやる！この<ruby>世<rt>よ</rt></ruby>から…<ruby>一匹<rt>いっぴき</rt></ruby><ruby>残<rt>のこ</rt></ruby>らず！","romaji":"Kuchiku shite yaru! Kono yo kara... ippiki nokorazu!","zh":"我要把它们驱逐出去！从这个世界上……一只不剩！","level":"N3","point":"「～てやる」表示说话人强烈的决心（有时带攻击性）。「残らず」＝「一个不剩、全部」。","example":"次の試合は絶対に勝ってやる！（下一场比赛我一定要赢！）","work":"進撃の巨人","workZh":"进击的巨人","ep":"第1話","speaker":"エレン・イェーガー","verify":true,"chunks":["駆逐して","やる！","この世から…","一匹残らず！"]},{"id":53,"jp":"個性捨てたら死んでるのと一緒だよ。","ruby":"<ruby>個性<rt>こせい</rt></ruby><ruby>捨<rt>す</rt></ruby>てたら<ruby>死<rt>し</rt></ruby>んでるのと<ruby>一緒<rt>いっしょ</rt></ruby>だよ。","romaji":"Kosei sutetara shinderu no to issho da yo.","zh":"抛弃个性的话，就跟死了一样。","level":"N3","point":"「Aと一緒だ」表示“和A一样”。日常比较两件事时可以说「～と同じ／一緒だ」。","example":"私のスマホ、あなたのと一緒だね。（我的手机跟你的一样呢。）","work":"ぼっち・ざ・ろっく！","workZh":"孤独摇滚！","ep":"","speaker":"山田リョウ","verify":true,"chunks":["個性","捨てたら","死んでるのと","一緒だよ。"]},{"id":54,"jp":"なんでもっと知ろうと思わなかったんだろう。","ruby":"なんでもっと<ruby>知<rt>し</rt></ruby>ろうと<ruby>思<rt>おも</rt></ruby>わなかったんだろう。","romaji":"Nande motto shirou to omowanakatta n darou.","zh":"为什么我当初没想过要多了解他一些呢。","level":"N3","point":"「意志形＋と思う」表示“打算、想要做……”；「なんで～んだろう」是带懊悔的自问。","example":"来年、日本へ行こうと思っています。（我打算明年去日本。）","work":"葬送のフリーレン","workZh":"葬送的芙莉莲","ep":"第1話","speaker":"フリーレン","verify":true,"chunks":["なんで","もっと","知ろうと","思わなかったんだろう。"]},{"id":56,"jp":"美しく最期を飾りつける暇があるなら、最後まで美しく生きようじゃねーか。","ruby":"<ruby>美<rt>うつく</rt></ruby>しく<ruby>最期<rt>さいご</rt></ruby>を<ruby>飾<rt>かざ</rt></ruby>りつける<ruby>暇<rt>ひま</rt></ruby>があるなら、<ruby>最後<rt>さいご</rt></ruby>まで<ruby>美<rt>うつく</rt></ruby>しく<ruby>生<rt>い</rt></ruby>きようじゃねーか。","romaji":"Utsukushiku saigo o kazaritsukeru hima ga aru nara, saigo made utsukushiku ikiyou ja nē ka.","zh":"与其有空把临终装点得漂漂亮亮，不如漂亮地活到最后吧。","level":"N3","point":"「意志形＋じゃないか」表示有力的号召“让我们……吧！”。「～暇があるなら」＝“有那闲工夫的话”。","example":"せっかくだから、みんなで楽しもうじゃないか。（难得嘛，大家一起好好玩吧！）","work":"銀魂","workZh":"银魂","ep":"","speaker":"坂田銀時","verify":true,"chunks":["美しく最期を","飾りつける暇が","あるなら、","最後まで","美しく","生きようじゃねーか。"]},{"id":57,"jp":"俺を誰だと思っていやがる！","ruby":"<ruby>俺<rt>おれ</rt></ruby>を<ruby>誰<rt>だれ</rt></ruby>だと<ruby>思<rt>おも</rt></ruby>っていやがる！","romaji":"Ore o dare da to omotte iyagaru!","zh":"你以为我是谁啊！","level":"N3","point":"「AをBだと思う」表示“把A看作B”。「～やがる」是很粗鲁的语尾，只在动漫里听听就好。","example":"みんな、彼を先生だと思っていた。（大家都以为他是老师。）","work":"天元突破グレンラガン","workZh":"天元突破 红莲螺岩","ep":"","speaker":"カミナ","verify":true,"chunks":["俺を","誰だと","思って","いやがる！"]},{"id":58,"jp":"嘘はとびきりの愛なんだよ。","ruby":"<ruby>嘘<rt>うそ</rt></ruby>はとびきりの<ruby>愛<rt>あい</rt></ruby>なんだよ。","romaji":"Uso wa tobikiri no ai nan da yo.","zh":"谎言是最极致的爱哦。","level":"N3","point":"「名词＋なんだよ」用于向对方解释、强调自己的看法，比「～だよ」更有“我跟你说”的感觉。","example":"これ、母の手作りなんだよ。（这个是我妈亲手做的哦。）","work":"【推しの子】","workZh":"我推的孩子","ep":"","speaker":"星野アイ","verify":true,"chunks":["嘘は","とびきりの","愛","なんだよ。"]},{"id":59,"jp":"親父にもぶたれたことないのに！","ruby":"<ruby>親父<rt>おやじ</rt></ruby>にもぶたれたことないのに！","romaji":"Oyaji ni mo butareta koto nai noni!","zh":"连老爸都没打过我！","level":"N3","point":"「动词た形＋ことがない」表示“从来没有……过”；「ぶたれた」是被动形。句尾「のに」表示不满。","example":"私はまだ富士山に登ったことがありません。（我还没爬过富士山。）","work":"機動戦士ガンダム","workZh":"机动战士高达","ep":"","speaker":"アムロ・レイ","verify":true,"chunks":["親父にも","ぶたれた","ことない","のに！"]},{"id":60,"jp":"奴はとんでもないものを盗んでいきました。","ruby":"<ruby>奴<rt>やつ</rt></ruby>はとんでもないものを<ruby>盗<rt>ぬす</rt></ruby>んでいきました。","romaji":"Yatsu wa tondemonai mono o nusunde ikimashita.","zh":"那家伙偷走了一样了不得的东西。","level":"N3","point":"「～ていく」表示动作完成后离开（“……走了”）。「とんでもない」意为“出乎意料、不得了”。","example":"猫が私のパンを持っていった！（猫把我的面包叼走了！）","work":"ルパン三世 カリオストロの城","workZh":"鲁邦三世：卡里奥斯特罗城","ep":"劇場版","speaker":"銭形警部","verify":true,"chunks":["奴は","とんでもない","ものを","盗んで","いきました。"]},{"jp":"絶対だいじょうぶだよ","ruby":"<ruby>絶対<rt>ぜったい</rt></ruby>だいじょうぶだよ","romaji":"Zettai daijōbu da yo","zh":"绝对没问题的。","level":"N5","point":"「だいじょうぶ」是“没事、没问题”，句尾「だよ」带着安慰、肯定的语气。前面加上「絶対（绝对）」，就成了小樱给自己打气的“无敌咒语”。","example":"「熱はもう下がった？」「うん、大丈夫だよ。」（“烧退了吗？”“嗯，没事了。”）","work":"カードキャプターさくら","workZh":"魔卡少女樱","ep":"","speaker":"木之本桜","chunks":["絶対","だいじょうぶ","だよ"],"verify":true,"id":61},{"jp":"わいとさくらは仲良し","ruby":"わいとさくらは<ruby>仲良<rt>なかよ</rt></ruby>し","romaji":"Wai to Sakura wa nakayoshi","zh":"我和小樱是好朋友。","level":"N5","point":"「AとBは仲良し」＝“A和B关系很好”，「と」表示并列“和”。「わい」是关西方言里的“我”，小可一直说关西腔，标准语说「僕」「私」就行。","example":"私と妹は仲良しです。（我和妹妹关系很好。）","work":"カードキャプターさくら","workZh":"魔卡少女樱","ep":"","speaker":"ケルベロス","chunks":["わいと","さくらは","仲良し"],"verify":true,"id":62},{"jp":"ポニョ、人間になるー！","ruby":"ポニョ、<ruby>人間<rt>にんげん</rt></ruby>になるー！","romaji":"Ponyo, ningen ni narū!","zh":"波妞要变成人类！","level":"N5","point":"「名词＋になる」表示“变成……”，是必会句型。小孩子说话爱把句尾拉长，所以成了「なるー」。","example":"弟は今年、二十歳になります。（弟弟今年满二十岁。）","work":"崖の上のポニョ","workZh":"悬崖上的金鱼姬","ep":"劇場版","speaker":"ポニョ","chunks":["ポニョ、","人間に","なるー！"],"verify":true,"id":63},{"jp":"僕、お魚のポニョも、半魚人のポニョも、人間のポニョも、みんな好きだよ","ruby":"<ruby>僕<rt>ぼく</rt></ruby>、お<ruby>魚<rt>さかな</rt></ruby>のポニョも、<ruby>半魚人<rt>はんぎょじん</rt></ruby>のポニョも、<ruby>人間<rt>にんげん</rt></ruby>のポニョも、みんな<ruby>好<rt>す</rt></ruby>きだよ","romaji":"Boku, osakana no Ponyo mo, hangyojin no Ponyo mo, ningen no Ponyo mo, minna suki da yo","zh":"我呀，鱼的波妞、半鱼人的波妞、人类的波妞，我全都喜欢。","level":"N5","point":"「AもBも」表示“A也好B也好”，可以一连并列好几样，最后用「みんな」总括成“全部”。","example":"犬も猫も好きです。（狗和猫我都喜欢。）","work":"崖の上のポニョ","workZh":"悬崖上的金鱼姬","ep":"劇場版","speaker":"宗介","chunks":["僕、","お魚のポニョも、","半魚人のポニョも、","人間のポニョも、","みんな好きだよ"],"verify":true,"id":64},{"jp":"私このパイ嫌いなのよね","ruby":"<ruby>私<rt>わたし</rt></ruby>このパイ<ruby>嫌<rt>きら</rt></ruby>いなのよね","romaji":"Watashi kono pai kirai na no yo ne","zh":"我讨厌这种派。","level":"N5","point":"「嫌い」是な形容词，意思是“讨厌”，和「好き」相对。句尾「なのよね」是女性口语，带着“我就是这样”的语气。当面对送东西的人这样说很失礼，日常想委婉一点可以说「ちょっと苦手です」。","example":"子どものころ、野菜が嫌いでした。（小时候我讨厌蔬菜。）","work":"魔女の宅急便","workZh":"魔女宅急便","ep":"劇場版","speaker":"老婦人の孫娘","chunks":["私","このパイ","嫌いなのよね"],"verify":true,"id":65},{"jp":"えらいよキキ、よくやったねぇ","ruby":"えらいよキキ、よくやったねぇ","romaji":"Erai yo Kiki, yoku yatta nē","zh":"真了不起啊琪琪，干得好！","level":"N5","point":"「よくやった」是夸人“干得好”的固定说法。「えらい」在口语里常用来夸“了不起、真棒”，多用于对晚辈或小孩。","example":"テスト100点？よくやったね！（考试一百分？干得漂亮！）","work":"魔女の宅急便","workZh":"魔女宅急便","ep":"劇場版","speaker":"おソノ","chunks":["えらいよ","キキ、","よくやったねぇ"],"verify":true,"id":66},{"jp":"夢だけど、夢じゃなかった！","ruby":"<ruby>夢<rt>ゆめ</rt></ruby>だけど、<ruby>夢<rt>ゆめ</rt></ruby>じゃなかった！","romaji":"Yume da kedo, yume ja nakatta!","zh":"是梦，但又不是梦！","level":"N5","point":"「名词＋じゃなかった」是名词句的过去否定，“（当时）不是……”。「けど」连接意思相反的前后两句，相当于“虽然……但是”。","example":"昨日は雨じゃなかったけど、寒かったです。（昨天虽然没下雨，但很冷。）","work":"となりのトトロ","workZh":"龙猫","ep":"劇場版","speaker":"サツキ・メイ","chunks":["夢","だけど、","夢じゃなかった！"],"verify":true,"id":67},{"jp":"メイ！私たち風になってる！","ruby":"メイ！<ruby>私<rt>わたし</rt></ruby>たち<ruby>風<rt>かぜ</rt></ruby>になってる！","romaji":"Mei! Watashitachi kaze ni natteru!","zh":"小梅！我们变成风了！","level":"N5","point":"「になっている」表示变化之后的状态“已经变成了……”。口语里常把「ている」说成「てる」。","example":"外はもう暗くなってるよ。（外面已经黑了哦。）","work":"となりのトトロ","workZh":"龙猫","ep":"劇場版","speaker":"サツキ","chunks":["メイ！","私たち","風になってる！"],"verify":true,"id":68},{"jp":"メイがとったトンモコロシ、お母さんにあげるの","ruby":"メイがとったトンモコロシ、お<ruby>母<rt>かあ</rt></ruby>さんにあげるの","romaji":"Mei ga totta tonmokoroshi, okāsan ni ageru no","zh":"小梅摘的玉米，要送给妈妈。","level":"N5","point":"动词た形可以直接修饰名词：「メイがとった＋トンモコロシ」＝“小梅摘的玉米”。「あげる」是“给（别人）”。小梅把「トウモロコシ（玉米）」说成了「トンモコロシ」，正确说法可别学错。","example":"これは私が作ったケーキです。（这是我做的蛋糕。）","work":"となりのトトロ","workZh":"龙猫","ep":"劇場版","speaker":"メイ","chunks":["メイが","とった","トンモコロシ、","お母さんに","あげるの"],"verify":true,"id":69},{"jp":"やあごめんごめん。探したよ","ruby":"やあごめんごめん。<ruby>探<rt>さが</rt></ruby>したよ","romaji":"Yā, gomen gomen. Sagashita yo","zh":"嘿，抱歉抱歉，我找你好久了。","level":"N5","point":"「ごめん」是「ごめんなさい」的随意说法，用在朋友之间；重复两遍显得很轻松。「探した」是「探す（找）」的过去式。","example":"ごめんごめん、ちょっと遅れた！（抱歉抱歉，迟到了一会儿！）","work":"ハウルの動く城","workZh":"哈尔的移动城堡","ep":"劇場版","speaker":"ハウル","chunks":["やあ","ごめんごめん。","探したよ"],"verify":true,"id":70},{"jp":"生きてる！おいら、自由だ！","ruby":"<ruby>生<rt>い</rt></ruby>きてる！おいら、<ruby>自由<rt>じゆう</rt></ruby>だ！","romaji":"Ikiteru! Oira, jiyū da!","zh":"我还活着！我自由了！","level":"N5","point":"「生きてる」是「生きている」的口语，表示“活着”的状态。「おいら」是很随意、带点土气的男性自称，日常说「僕」「俺」更常见。","example":"この金魚、まだ生きてる？（这条金鱼还活着吗？）","work":"ハウルの動く城","workZh":"哈尔的移动城堡","ep":"劇場版","speaker":"カルシファー","chunks":["生きてる！","おいら、","自由だ！"],"verify":true,"id":71},{"jp":"きれいな火だねぇ","ruby":"きれいな<ruby>火<rt>ひ</rt></ruby>だねぇ","romaji":"Kirei na hi da nē","zh":"真漂亮的火啊。","level":"N5","point":"な形容词修饰名词时要加「な」：「きれい＋な＋火」。句尾的「ねぇ」拉长，表示感叹。","example":"きれいな部屋ですね。（真干净的房间啊。）","work":"ハウルの動く城","workZh":"哈尔的移动城堡","ep":"劇場版","speaker":"荒地の魔女","chunks":["きれいな","火","だねぇ"],"verify":true,"id":72},{"jp":"そう…じゃあ夏目くんの宝物なのね","ruby":"そう…じゃあ<ruby>夏目<rt>なつめ</rt></ruby>くんの<ruby>宝物<rt>たからもの</rt></ruby>なのね","romaji":"Sō… jā Natsume-kun no takaramono na no ne","zh":"这样啊……那就是夏目同学的宝物了呢。","level":"N5","point":"「じゃあ」是“那么”，根据对方的话得出结论。「名词＋なのね」用来温和地确认“原来是……啊”。","example":"じゃあ、これは田中さんの傘なのね。（那这是田中的伞吧。）","work":"夏目友人帳","workZh":"夏目友人帐","ep":"","speaker":"多軌透","chunks":["そう…","じゃあ","夏目くんの","宝物なのね"],"verify":true,"id":73},{"jp":"そう…よかった。ひとりじゃないのね","ruby":"そう…よかった。ひとりじゃないのね","romaji":"Sō… yokatta. Hitori ja nai no ne","zh":"这样啊……太好了。你不是一个人了呢。","level":"N5","point":"「よかった」是「いい」的过去式，用来表达“太好了、放心了”。「ひとりじゃない」＝“不是一个人”。","example":"道がわかった？よかった！（找到路了？太好了！）","work":"夏目友人帳","workZh":"夏目友人帐","ep":"","speaker":"","chunks":["そう…","よかった。","ひとりじゃないのね"],"verify":true,"id":74},{"jp":"今でもイチョウは大好きですよー！！！","ruby":"<ruby>今<rt>いま</rt></ruby>でもイチョウは<ruby>大好<rt>だいす</rt></ruby>きですよー！！！","romaji":"Ima demo ichō wa daisuki desu yō!","zh":"我到现在还是最喜欢银杏！","level":"N5","point":"「大好き」比「好き」程度更强，“非常喜欢”。「今でも」＝“到现在也还……”，表示一直没变。","example":"子どものころから、今でもアニメが大好きです。（我从小到现在都很喜欢动画。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"阿笠博士","chunks":["今でも","イチョウは","大好きですよー！！！"],"verify":true,"id":75},{"jp":"あったかいふとんで、ぐっすりねる！こんな楽しいことがあるか。","ruby":"あったかいふとんで、ぐっすりねる！こんな<ruby>楽<rt>たの</rt></ruby>しいことがあるか。","romaji":"Attakai futon de, gussuri neru! Konna tanoshii koto ga aru ka.","zh":"在暖和的被窝里美美地睡一觉！还有比这更快乐的事吗？","level":"N5","point":"「こんな～ことがあるか」是反问，意思是“哪还有比这更……的事”。「あったかい」是「あたたかい」的口语说法。","example":"こんなおいしいラーメンがあるか！（哪有这么好吃的拉面！）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"のび太","chunks":["あったかいふとんで、","ぐっすりねる！","こんな楽しいことが","あるか。"],"verify":true,"id":76},{"jp":"のび太、力をかすぜ！","ruby":"のび<ruby>太<rt>た</rt></ruby>、<ruby>力<rt>ちから</rt></ruby>をかすぜ！","romaji":"Nobita, chikara o kasu ze!","zh":"大雄，我来助你一臂之力！","level":"N5","point":"「力をかす」直译是“借出力量”，就是“帮忙”。「かす（借出）」和「かりる（借入）」方向相反，要分清。句尾「ぜ」是男性很随意的语气。","example":"友達にペンを貸しました。（我把笔借给了朋友。）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"ジャイアン","chunks":["のび太、","力を","かすぜ！"],"verify":true,"id":77},{"jp":"この町で、俺にかなうものはいない。俺は王様だ。","ruby":"この<ruby>町<rt>まち</rt></ruby>で、<ruby>俺<rt>おれ</rt></ruby>にかなうものはいない。<ruby>俺<rt>おれ</rt></ruby>は<ruby>王様<rt>おうさま</rt></ruby>だ。","romaji":"Kono machi de, ore ni kanau mono wa inai. Ore wa ōsama da.","zh":"在这个镇上，没人比得过我。我就是国王。","level":"N5","point":"「～はいない」表示“没有（人或动物）”：人和动物的存在用「いる／いない」，东西用「ある／ない」。「かなう」是“比得上”。","example":"教室にはだれもいません。（教室里一个人也没有。）","work":"ドラえもん","workZh":"哆啦A梦","ep":"","speaker":"ジャイアン","chunks":["この町で、","俺にかなうものは","いない。","俺は","王様だ。"],"verify":true,"id":78},{"jp":"俺は世界最強のサラリーマン！","ruby":"<ruby>俺<rt>おれ</rt></ruby>は<ruby>世界<rt>せかい</rt></ruby><ruby>最強<rt>さいきょう</rt></ruby>のサラリーマン！","romaji":"Ore wa sekai saikyō no sarariiman!","zh":"我是世界最强的上班族！","level":"N5","point":"「AはBだ」的判断句，口语里常把「だ」省掉。「サラリーマン」是和制英语，指公司职员、上班族。「俺」是男性随意的自称，正式场合用「私」。","example":"父はサラリーマンです。（我爸爸是上班族。）","work":"クレヨンしんちゃん","workZh":"蜡笔小新","ep":"","speaker":"野原ひろし","chunks":["俺は","世界最強の","サラリーマン！"],"verify":true,"id":79},{"jp":"僕の友達は心がエリートです","ruby":"<ruby>僕<rt>ぼく</rt></ruby>の<ruby>友達<rt>ともだち</rt></ruby>は<ruby>心<rt>こころ</rt></ruby>がエリートです","romaji":"Boku no tomodachi wa kokoro ga eriito desu","zh":"我的朋友们，内心都是精英。","level":"N5","point":"「AはBがC」句型：A是话题，B是A的一部分，C描述B，和「象は鼻が長い（大象鼻子长）」一样。","example":"姉は髪が長いです。（姐姐头发很长。）","work":"クレヨンしんちゃん","workZh":"蜡笔小新","ep":"","speaker":"風間くん","chunks":["僕の友達は","心が","エリートです"],"verify":true,"id":80},{"jp":"来週もまた見てくださいね！","ruby":"<ruby>来週<rt>らいしゅう</rt></ruby>もまた<ruby>見<rt>み</rt></ruby>てくださいね！","romaji":"Raishū mo mata mite kudasai ne!","zh":"下周也请继续收看哦！","level":"N5","point":"「て形＋ください」是礼貌地请求“请……”，句尾加「ね」更亲切。「また」是“再、又”。","example":"また遊びに来てくださいね。（欢迎再来玩哦。）","work":"サザエさん","workZh":"海螺小姐","ep":"","speaker":"サザエ","chunks":["来週も","また","見てくださいね！"],"verify":true,"id":81},{"jp":"アンパンマン！新しい顔よ！","ruby":"アンパンマン！<ruby>新<rt>あたら</rt></ruby>しい<ruby>顔<rt>かお</rt></ruby>よ！","romaji":"Anpanman! Atarashii kao yo!","zh":"面包超人！新的脸来啦！","level":"N5","point":"い形容词可以直接修饰名词：「新しい＋顔」。句尾「よ」用来把新信息告诉对方、提醒对方注意。","example":"新しいかばんを買いました。（我买了新包。）","work":"それいけ!アンパンマン","workZh":"面包超人","ep":"","speaker":"バタコさん","chunks":["アンパンマン！","新しい","顔よ！"],"verify":true,"id":82},{"jp":"アーニャおうちかえりたい","ruby":"アーニャおうちかえりたい","romaji":"Ānya ouchi kaeritai","zh":"阿尼亚想回家。","level":"N5","point":"「动词ます形去掉ます＋たい」表示“想做……”：「かえります→かえりたい」。阿尼亚用自己的名字当“我”，是小孩子的说法。","example":"今日は早く家に帰りたいです。（今天想早点回家。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ","chunks":["アーニャ","おうち","かえりたい"],"verify":true,"id":83},{"jp":"ちちもははもおもしろくてだいすきです","ruby":"ちちもははもおもしろくてだいすきです","romaji":"Chichi mo haha mo omoshirokute daisuki desu","zh":"爸爸和妈妈都很有趣，我最喜欢他们了。","level":"N5","point":"い形容词的て形「おもしろい→おもしろくて」可以连接后句，表示原因或并列。「ちち」「はは」是对外人说自己父母时的叫法。","example":"この店は安くておいしいです。（这家店又便宜又好吃。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ","chunks":["ちちも","ははも","おもしろくて","だいすきです"],"verify":true,"id":84},{"jp":"ずっといっしょがいいです","ruby":"ずっといっしょがいいです","romaji":"Zutto issho ga ii desu","zh":"我想一直在一起。","level":"N5","point":"「～がいいです」表示“……比较好、我要……”，用来说出自己的选择。「ずっと」是“一直”。","example":"飲み物は、お茶がいいです。（饮料的话，我要茶。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ","chunks":["ずっと","いっしょが","いいです"],"verify":true,"id":85},{"jp":"アーニャつよくてかっこいいははすき！","ruby":"アーニャつよくてかっこいいははすき！","romaji":"Ānya tsuyokute kakkoii haha suki!","zh":"阿尼亚喜欢又强又帅的妈妈！","level":"N5","point":"两个い形容词一起修饰名词时，前一个变成て形：「つよい→つよくて」＋「かっこいい」＋「はは」。阿尼亚说话常把「は」「が」省掉，完整说法是「アーニャは～ははが好き」。","example":"大きくて明るい部屋がいいです。（想要又大又亮的房间。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ","chunks":["アーニャ","つよくて","かっこいい","ははすき！"],"verify":true,"id":86},{"jp":"親方、空から女の子が！","ruby":"<ruby>親方<rt>おやかた</rt></ruby>、<ruby>空<rt>そら</rt></ruby>から<ruby>女<rt>おんな</rt></ruby>の<ruby>子<rt>こ</rt></ruby>が！","romaji":"Oyakata, sora kara onnanoko ga!","zh":"师傅，有个女孩从天上掉下来了！","level":"N5","point":"「から」表示起点“从……”。句子说到「が」就断了，省掉了「落ちてきた（掉下来了）」，人在吃惊时常常只说半句。","example":"駅から学校まで歩きます。（从车站走到学校。）","work":"天空の城ラピュタ","workZh":"天空之城","ep":"劇場版","speaker":"パズー","chunks":["親方、","空から","女の子が！"],"verify":true,"id":87},{"jp":"知らない天井だ","ruby":"<ruby>知<rt>し</rt></ruby>らない<ruby>天井<rt>てんじょう</rt></ruby>だ","romaji":"Shiranai tenjō da","zh":"陌生的天花板。","level":"N5","point":"动词ない形可以直接修饰名词：「知らない＋天井」＝“不认识的天花板”。「知らない人（陌生人）」也是同样的用法。","example":"知らない言葉は辞書で調べます。（不认识的词就查词典。）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"第2話","speaker":"碇シンジ","chunks":["知らない","天井","だ"],"verify":true,"id":88},{"jp":"私、にんにくラーメン、チャーシュー抜き","ruby":"<ruby>私<rt>わたし</rt></ruby>、にんにくラーメン、チャーシュー<ruby>抜<rt>ぬ</rt></ruby>き","romaji":"Watashi, ninniku rāmen, chāshū nuki","zh":"我要大蒜拉面，不要叉烧。","level":"N5","point":"点餐时可以直接说「私、～」表示“我要……”。「名词＋抜き」表示“去掉……”，比如「わさび抜き（不要芥末）」。","example":"コーヒー、砂糖抜きでお願いします。（咖啡不要加糖，谢谢。）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"","speaker":"綾波レイ","chunks":["私、","にんにくラーメン、","チャーシュー抜き"],"verify":true,"id":89},{"jp":"風呂は心の洗濯よ","ruby":"<ruby>風呂<rt>ふろ</rt></ruby>は<ruby>心<rt>こころ</rt></ruby>の<ruby>洗濯<rt>せんたく</rt></ruby>よ","romaji":"Furo wa kokoro no sentaku yo","zh":"泡澡就是给心灵洗个衣服。","level":"N5","point":"「AはBよ」是女性口语里的判断句，省掉了「だ」。这里用比喻说泡澡能洗去心里的疲惫。日常一般说「お風呂」。","example":"音楽は心の薬です。（音乐是心灵的良药。）","work":"新世紀エヴァンゲリオン","workZh":"新世纪福音战士","ep":"第2話","speaker":"葛城ミサト","chunks":["風呂は","心の","洗濯よ"],"verify":true,"id":90},{"jp":"上杉達也は浅倉南を愛しています","ruby":"<ruby>上杉<rt>うえすぎ</rt></ruby><ruby>達也<rt>たつや</rt></ruby>は<ruby>浅倉<rt>あさくら</rt></ruby><ruby>南<rt>みなみ</rt></ruby>を<ruby>愛<rt>あい</rt></ruby>しています","romaji":"Uesugi Tatsuya wa Asakura Minami o aishite imasu","zh":"上杉达也爱着浅仓南。","level":"N5","point":"「愛しています」用「ている」表示持续的状态“一直爱着”。用自己的全名来告白，显得郑重又笨拙。日常表白说「好きです」更自然。","example":"私は東京に住んでいます。（我住在东京。）","work":"タッチ","workZh":"棒球英豪","ep":"","speaker":"上杉達也","chunks":["上杉達也は","浅倉南を","愛しています"],"verify":true,"id":91},{"jp":"今いるこの講堂が、私たちの武道館です！","ruby":"<ruby>今<rt>いま</rt></ruby>いるこの<ruby>講堂<rt>こうどう</rt></ruby>が、<ruby>私<rt>わたし</rt></ruby>たちの<ruby>武道館<rt>ぶどうかん</rt></ruby>です！","romaji":"Ima iru kono kōdō ga, watashitachi no Budōkan desu!","zh":"我们现在所在的这个礼堂，就是我们的武道馆！","level":"N5","point":"动词原形可以直接修饰名词：「今いる＋この講堂」＝“现在所在的这个礼堂”。武道馆是日本乐队梦想登上的演出场地。","example":"今住んでいる町が大好きです。（我很喜欢现在住的城市。）","work":"けいおん!!","workZh":"轻音少女","ep":"","speaker":"平沢唯","chunks":["今いる","この講堂が、","私たちの","武道館です！"],"verify":true,"id":92},{"jp":"ぼくは本当に幸せだった","ruby":"ぼくは<ruby>本当<rt>ほんとう</rt></ruby>に<ruby>幸<rt>しあわ</rt></ruby>せだった","romaji":"Boku wa hontō ni shiawase datta","zh":"我真的很幸福。","level":"N5","point":"な形容词的过去式是「～だった」：「幸せだ→幸せだった」。「本当に」＝“真的”，用来加强语气。","example":"子どものころ、この町は静かだった。（小时候这个镇子很安静。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"ゴーイングメリー号","chunks":["ぼくは","本当に","幸せだった"],"verify":true,"id":93},{"jp":"仕事の後の一杯が楽しみだなッ!!","ruby":"<ruby>仕事<rt>しごと</rt></ruby>の<ruby>後<rt>あと</rt></ruby>の<ruby>一杯<rt>いっぱい</rt></ruby>が<ruby>楽<rt>たの</rt></ruby>しみだなッ!!","romaji":"Shigoto no ato no ippai ga tanoshimi da na!!","zh":"真期待下班后的那一碗啊！","level":"N5","point":"「名词＋の後」表示“……之后”。「～が楽しみだ」＝“期待……”，是非常常用的说法。「一杯」可以指一碗面，也常指喝一杯。","example":"週末の旅行が楽しみです。（很期待周末的旅行。）","work":"ちいかわ","workZh":"吉伊卡哇","ep":"","speaker":"ラーメンの鎧さん","chunks":["仕事の後の","一杯が","楽しみだなッ!!"],"verify":true,"id":94},{"jp":"でもこれも…「味」だよねッ","ruby":"でもこれも…「<ruby>味<rt>あじ</rt></ruby>」だよねッ","romaji":"Demo kore mo… “aji” da yo ne!","zh":"不过这也算是一种“味道”吧！","level":"N5","point":"「これも」的「も」表示“这也……”。「味」除了“味道”，还能指“韵味、独特的感觉”，就算不完美也可以说成是一种风味。","example":"この古いカメラも、味がありますね。（这台旧相机也很有味道呢。）","work":"ちいかわ","workZh":"吉伊卡哇","ep":"","speaker":"ハチワレ","chunks":["でも","これも…","「味」だよねッ"],"verify":true,"id":95},{"jp":"お前の妹は美人だよ","ruby":"お<ruby>前<rt>まえ</rt></ruby>の<ruby>妹<rt>いもうと</rt></ruby>は<ruby>美人<rt>びじん</rt></ruby>だよ","romaji":"Omae no imōto wa bijin da yo","zh":"你妹妹是个美人。","level":"N5","point":"「AはBだよ」是口语判断句，「よ」用来告诉对方自己的看法。「お前」是男性对平辈或晚辈的随意叫法，对别人用会显得粗鲁，日常用「〇〇さん」更好。","example":"田中さんの妹さんは先生ですよ。（田中的妹妹是老师哦。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"愈史郎","chunks":["お前の","妹は","美人だよ"],"verify":true,"id":96},{"jp":"俺たちは二人で一つだからなあ","ruby":"<ruby>俺<rt>おれ</rt></ruby>たちは<ruby>二人<rt>ふたり</rt></ruby>で<ruby>一<rt>ひと</rt></ruby>つだからなあ","romaji":"Oretachi wa futari de hitotsu da kara nā","zh":"因为我们是两人一体啊。","level":"N5","point":"「数量＋で」表示“以……的人数（单位）”：「二人で」＝“两个人一起”。句尾的「から」表示原因“因为……”。","example":"週末は家族四人で旅行します。（周末一家四口去旅行。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"妓夫太郎","chunks":["俺たちは","二人で","一つだからなあ"],"verify":true,"id":97},{"jp":"バスケットは…お好きですか","ruby":"バスケットは…お<ruby>好<rt>す</rt></ruby>きですか","romaji":"Basuketto wa… osuki desu ka","zh":"你……喜欢篮球吗？","level":"N5","point":"「～は好きですか」是询问喜好的基本句型。前面加「お」变成「お好きですか」，更礼貌，适合问不太熟的人。","example":"日本料理はお好きですか。（您喜欢日本料理吗？）","work":"SLAM DUNK","workZh":"灌篮高手","ep":"第1話","speaker":"赤木晴子","chunks":["バスケットは…","お好き","ですか"],"verify":true,"id":98},{"jp":"天才ですから","ruby":"<ruby>天才<rt>てんさい</rt></ruby>ですから","romaji":"Tensai desu kara","zh":"因为我是天才嘛。","level":"N5","point":"「から」表示原因。放在句末、省掉后半句时，就成了“因为……嘛”的语气。樱木常用这句来自夸，对别人说会显得很自负。","example":"「早いね！」「毎日練習していますから。」（“真快！”“因为我每天都在练习嘛。”）","work":"SLAM DUNK","workZh":"灌篮高手","ep":"","speaker":"桜木花道","chunks":["天才","です","から"],"verify":true,"id":99},{"jp":"ここから始めましょう。ゼロから！","ruby":"ここから<ruby>始<rt>はじ</rt></ruby>めましょう。ゼロから！","romaji":"Koko kara hajimemashō. Zero kara!","zh":"就从这里开始吧。从零开始！","level":"N5","point":"「动词ます形去掉ます＋ましょう」表示“一起……吧”的提议。「から」表示起点“从……”。","example":"じゃあ、十時から始めましょう。（那就从十点开始吧。）","work":"Re:ゼロから始める異世界生活","workZh":"Re：从零开始的异世界生活","ep":"第18話","speaker":"レム","chunks":["ここから","始めましょう。","ゼロから！"],"verify":true,"id":100},{"jp":"あなたは、だれ、ですか？","ruby":"あなたは、だれ、ですか？","romaji":"Anata wa, dare, desu ka?","zh":"你是……谁？","level":"N5","point":"「だれですか」问“是谁”。这里一个词一个词地停顿，表现出失去记忆后的茫然。问长辈或陌生人更礼貌的说法是「どなたですか」。","example":"すみません、あの人はだれですか。（请问那个人是谁？）","work":"Re:ゼロから始める異世界生活","workZh":"Re：从零开始的异世界生活","ep":"","speaker":"レム","chunks":["あなたは、","だれ、","ですか？"],"verify":true,"id":101},{"jp":"世界中全部のポケモンと友達になりたい。","ruby":"<ruby>世界中<rt>せかいじゅう</rt></ruby><ruby>全部<rt>ぜんぶ</rt></ruby>のポケモンと<ruby>友達<rt>ともだち</rt></ruby>になりたい。","romaji":"Sekaijū zenbu no Pokemon to tomodachi ni naritai.","zh":"我想和全世界所有的宝可梦成为朋友。","level":"N5","point":"「～と友達になりたい」＝“想和……成为朋友”。「と」表示对象“和……”，「になる」表示变成，「たい」表示愿望。","example":"クラスのみんなと友達になりたいです。（想和班上所有人成为朋友。）","work":"ポケットモンスター","workZh":"宝可梦","ep":"","speaker":"サトシ","chunks":["世界中","全部のポケモンと","友達に","なりたい。"],"verify":true,"id":102},{"jp":"ルビー、アクア、愛してる。","ruby":"ルビー、アクア、<ruby>愛<rt>あい</rt></ruby>してる。","romaji":"Rubī, Akua, aishiteru.","zh":"露比、阿库亚，我爱你们。","level":"N5","point":"「愛してる」是「愛している」的口语形。比「好き」更深沉郑重，日本人日常其实很少直接说出口。","example":"父は今、テレビを見てる。（爸爸现在在看电视。）","work":"【推しの子】","workZh":"我推的孩子","ep":"第1話","speaker":"星野アイ","chunks":["ルビー、","アクア、","愛してる。"],"verify":true,"id":103},{"jp":"“俺の仲間”はちゃんと強いよ","ruby":"“<ruby>俺<rt>おれ</rt></ruby>の<ruby>仲間<rt>なかま</rt></ruby>”はちゃんと<ruby>強<rt>つよ</rt></ruby>いよ","romaji":"“Ore no nakama” wa chanto tsuyoi yo","zh":"“我的伙伴们”可是真的很强。","level":"N5","point":"い形容词可以直接结句：「強い＋よ」。「ちゃんと」原意是“好好地、确实”，这里表示“真的、确确实实”。","example":"この店のラーメン、ちゃんとおいしいよ。（这家的拉面确实好吃哦。）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"菅原孝支","chunks":["“俺の仲間”は","ちゃんと","強いよ"],"verify":true,"id":104},{"jp":"どんな女がタイプだ","ruby":"どんな<ruby>女<rt>おんな</rt></ruby>がタイプだ","romaji":"Donna onna ga taipu da","zh":"你喜欢什么样的女人？","level":"N5","point":"「どんな＋名词」问“什么样的……”。「タイプ」指喜欢的类型。东堂问得很冲，日常问朋友可以说「どんな人がタイプ？」。","example":"どんな音楽が好きですか。（你喜欢什么样的音乐？）","work":"呪術廻戦","workZh":"咒术回战","ep":"","speaker":"東堂葵","chunks":["どんな","女が","タイプだ"],"verify":true,"id":105},{"jp":"俺は長男だから我慢できたけど、次男だったら我慢できなかった","ruby":"<ruby>俺<rt>おれ</rt></ruby>は<ruby>長男<rt>ちょうなん</rt></ruby>だから<ruby>我慢<rt>がまん</rt></ruby>できたけど、<ruby>次男<rt>じなん</rt></ruby>だったら<ruby>我慢<rt>がまん</rt></ruby>できなかった","romaji":"Ore wa chōnan dakara gaman dekita kedo, jinan dattara gaman dekinakatta","zh":"我是长子所以忍住了，要是次子的话就忍不住了。","level":"N4","point":"「名词＋だったら」是“如果是……的话”的假设说法；「我慢できる」是“能忍住”，这里用过去式「できた／できなかった」说已经发生的事。","example":"雨だったら、試合は来週になります。（如果下雨的话，比赛就改到下周。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"竈門炭治郎","chunks":["俺は長男だから","我慢できたけど、","次男だったら","我慢できなかった"],"verify":true,"id":106},{"jp":"俺と禰豆子の絆は誰にも引き裂けない！","ruby":"<ruby>俺<rt>おれ</rt></ruby>と<ruby>禰豆子<rt>ねずこ</rt></ruby>の<ruby>絆<rt>きずな</rt></ruby>は<ruby>誰<rt>だれ</rt></ruby>にも<ruby>引<rt>ひ</rt></ruby>き<ruby>裂<rt>さ</rt></ruby>けない！","romaji":"Ore to Nezuko no kizuna wa dare ni mo hikisakenai!","zh":"我和祢豆子的羁绊，谁也拆不散！","level":"N4","point":"五段动词把词尾的う段换成え段再加「る」就是可能形：「引き裂く」→「引き裂ける」（能撕开），否定是「引き裂けない」。「誰にも～ない」＝“谁都不能……”。","example":"この漢字は難しくて、誰にも読めない。（这个汉字太难，谁都读不出来。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"竈門炭治郎","chunks":["俺と禰豆子の","絆は","誰にも","引き裂けない！"],"verify":true,"id":107},{"jp":"人は心が原動力だから心はどこまでも強くなれる！","ruby":"<ruby>人<rt>ひと</rt></ruby>は<ruby>心<rt>こころ</rt></ruby>が<ruby>原動力<rt>げんどうりょく</rt></ruby>だから<ruby>心<rt>こころ</rt></ruby>はどこまでも<ruby>強<rt>つよ</rt></ruby>くなれる！","romaji":"Hito wa kokoro ga gendōryoku dakara kokoro wa doko made mo tsuyoku nareru!","zh":"人是靠心来驱动的，所以心可以无限地变强！","level":"N4","point":"「形容词く＋なる」＝“变得……”，「なる」的可能形是「なれる」，所以「強くなれる」＝“能变强”。「どこまでも」＝“无止境地”。","example":"毎日練習すれば、もっと上手になれるよ。（每天练习的话，就能变得更厉害哦。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"竈門炭治郎","chunks":["人は","心が原動力だから","心は","どこまでも","強くなれる！"],"verify":true,"id":108},{"jp":"それに裏が出ても、表が出るまで何度でも投げ続けようと思ってたから","ruby":"それに<ruby>裏<rt>うら</rt></ruby>が<ruby>出<rt>で</rt></ruby>ても、<ruby>表<rt>おもて</rt></ruby>が<ruby>出<rt>で</rt></ruby>るまで<ruby>何度<rt>なんど</rt></ruby>でも<ruby>投<rt>な</rt></ruby>げ<ruby>続<rt>つづ</rt></ruby>けようと<ruby>思<rt>おも</rt></ruby>ってたから","romaji":"Sore ni ura ga dete mo, omote ga deru made nando demo nagetsuzukeyō to omotteta kara","zh":"而且就算扔出了反面，我也打算一直扔到出正面为止。","level":"N4","point":"「意志形＋と思っていた」＝“（当时）打算……”，口语里常缩成「思ってた」。「～ても」＝“即使……也”。","example":"雨が降っても、散歩に行こうと思ってた。（就算下雨，我也打算去散步的。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"竈門炭治郎","chunks":["それに裏が出ても、","表が出るまで","何度でも","投げ続けようと思ってたから"],"verify":true,"id":109},{"jp":"自分が死ぬ時のことは分からんけど、生き様で後悔はしたくない","ruby":"<ruby>自分<rt>じぶん</rt></ruby>が<ruby>死<rt>し</rt></ruby>ぬ<ruby>時<rt>とき</rt></ruby>のことは<ruby>分<rt>わ</rt></ruby>からんけど、<ruby>生<rt>い</rt></ruby>き<ruby>様<rt>ざま</rt></ruby>で<ruby>後悔<rt>こうかい</rt></ruby>はしたくない","romaji":"Jibun ga shinu toki no koto wa wakaran kedo, ikizama de kōkai wa shitakunai","zh":"我不知道自己会怎么死，但我不想对自己的活法感到后悔。","level":"N4","point":"「～たくない」是「～たい」的否定，“不想……”。「分からん」是「分からない」的口语说法，正式场合说「分かりません」。","example":"明日は雨だから、出かけたくない。（明天下雨，不想出门。）","work":"呪術廻戦","workZh":"咒术回战","ep":"","speaker":"虎杖悠仁","chunks":["自分が死ぬ時のことは","分からんけど、","生き様で","後悔はしたくない"],"verify":true,"id":110},{"jp":"オマエは強いから人を助けろ","ruby":"オマエは<ruby>強<rt>つよ</rt></ruby>いから<ruby>人<rt>ひと</rt></ruby>を<ruby>助<rt>たす</rt></ruby>けろ","romaji":"Omae wa tsuyoi kara hito o tasukero","zh":"你很强，所以要去帮助别人。","level":"N4","point":"「助けろ」是一段动词「助ける」的命令形（る→ろ），语气很强，多是长辈对晚辈说。日常请别人帮忙要说「助けてください」。","example":"危ない！早く逃げろ！（危险！快逃！）","work":"呪術廻戦","workZh":"咒术回战","ep":"第1話","speaker":"虎杖倭助","chunks":["オマエは","強いから","人を","助けろ"],"verify":true,"id":111},{"jp":"でも死なせたくありません","ruby":"でも<ruby>死<rt>し</rt></ruby>なせたくありません","romaji":"Demo shinasetaku arimasen","zh":"但是，我不想让他死。","level":"N4","point":"「死なせる」是「死ぬ」的使役形，“让……死”；后面接「たくありません」就是“不想让……”。「たくない」的礼貌说法是「たくありません」或「たくないです」。","example":"子供に無理をさせたくありません。（我不想让孩子太勉强自己。）","work":"呪術廻戦","workZh":"咒术回战","ep":"","speaker":"伏黒恵","chunks":["でも","死なせたく","ありません"],"verify":true,"id":112},{"jp":"誰かを呪う暇があったら、大切な人のことを考えていたいの","ruby":"<ruby>誰<rt>だれ</rt></ruby>かを<ruby>呪<rt>のろ</rt></ruby>う<ruby>暇<rt>ひま</rt></ruby>があったら、<ruby>大切<rt>たいせつ</rt></ruby>な<ruby>人<rt>ひと</rt></ruby>のことを<ruby>考<rt>かんが</rt></ruby>えていたいの","romaji":"Dareka o norou hima ga attara, taisetsu na hito no koto o kangaete itai no","zh":"有空去诅咒别人的话，我更想一直想着重要的人。","level":"N4","point":"「～暇があったら」＝“有……的工夫的话（不如……）”，常用来劝人别把时间浪费在没用的事上。「ていたい」＝“想一直保持……”。","example":"スマホを見る暇があったら、単語を一つ覚えよう。（有玩手机的工夫，不如记一个单词吧。）","work":"呪術廻戦","workZh":"咒术回战","ep":"","speaker":"伏黒津美紀","chunks":["誰かを呪う","暇があったら、","大切な人のことを","考えていたいの"],"verify":true,"id":113},{"jp":"負けたくないことに理由って要る？","ruby":"<ruby>負<rt>ま</rt></ruby>けたくないことに<ruby>理由<rt>りゆう</rt></ruby>って<ruby>要<rt>い</rt></ruby>る？","romaji":"Maketakunai koto ni riyū tte iru?","zh":"不想输，还需要理由吗？","level":"N4","point":"口语里「～って」常代替「は」来提起话题。「要る」＝“需要”，和「いる（在）」同音，写汉字就能分清。","example":"好きなことに理由って要る？（喜欢一件事还需要理由吗？）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"日向翔陽","chunks":["負けたくないことに","理由って","要る？"],"verify":true,"id":114},{"jp":"逃げる方が絶対後からしんどいって事はもう知ってる","ruby":"<ruby>逃<rt>に</rt></ruby>げる<ruby>方<rt>ほう</rt></ruby>が<ruby>絶対<rt>ぜったい</rt></ruby><ruby>後<rt>あと</rt></ruby>からしんどいって<ruby>事<rt>こと</rt></ruby>はもう<ruby>知<rt>し</rt></ruby>ってる","romaji":"Nigeru hō ga zettai ato kara shindoi tte koto wa mō shitteru","zh":"我已经知道了，逃避的话事后绝对会更难受。","level":"N4","point":"「～方が…」用来比较，“……的那一边更……”。「知っている」表示“知道”，口语缩成「知ってる」；注意“不知道”是「知らない」，不说「知っていない」。","example":"早く寝た方が、次の日楽だよ。（早点睡的话，第二天更轻松。）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"縁下力","chunks":["逃げる方が","絶対後から","しんどいって事は","もう知ってる"],"verify":true,"id":115},{"jp":"おれにバレーボール教えてくれてありがとう","ruby":"おれにバレーボール<ruby>教<rt>おし</rt></ruby>えてくれてありがとう","romaji":"Ore ni barēbōru oshiete kurete arigatō","zh":"谢谢你教会我打排球。","level":"N4","point":"「～てくれてありがとう」＝“谢谢你为我……”，「てくれる」表示别人为我做了某事。道谢时非常常用。","example":"手伝ってくれてありがとう。（谢谢你帮我。）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"孤爪研磨","chunks":["おれに","バレーボール","教えてくれて","ありがとう"],"verify":true,"id":116},{"jp":"背中は俺が護ってやるぜ","ruby":"<ruby>背中<rt>せなか</rt></ruby>は<ruby>俺<rt>おれ</rt></ruby>が<ruby>護<rt>まも</rt></ruby>ってやるぜ","romaji":"Senaka wa ore ga mamotte yaru ze","zh":"背后就交给我来守护吧！","level":"N4","point":"「～てやる」＝“（我）为你做……”，对平辈或晚辈说，听起来很豪爽；对长辈要用「～てあげる」或更礼貌的说法。「護る」一般写作「守る」。","example":"宿題、見てやるよ。（作业我帮你看看吧。）","work":"ハイキュー!!","workZh":"排球少年!!","ep":"","speaker":"西谷夕","chunks":["背中は","俺が","護ってやるぜ"],"verify":true,"id":117},{"jp":"アーニャははみたいになりたい","ruby":"アーニャははみたいになりたい","romaji":"Ānya haha mitai ni naritai","zh":"阿尼亚想变得像妈妈一样。","level":"N4","point":"「名词＋みたいになりたい」＝“想变成像……一样”，「みたい」是「のよう」的口语说法。「はは」就是「母」，阿尼亚这样叫约尔，平时叫妈妈一般说「お母さん」。","example":"将来、先生みたいになりたい。（将来想成为像老师那样的人。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"","speaker":"アーニャ・フォージャー","chunks":["アーニャ","ははみたいに","なりたい"],"verify":true,"id":118},{"jp":"私にできることを精一杯がんばろう！","ruby":"<ruby>私<rt>わたし</rt></ruby>にできることを<ruby>精一杯<rt>せいいっぱい</rt></ruby>がんばろう！","romaji":"Watashi ni dekiru koto o seiippai ganbarō!","zh":"尽全力做好我能做的事吧！","level":"N4","point":"「がんばろう」是「がんばる」的意志形，表示“（我）要……吧”，常用来给自己打气。「～にできること」＝“……能做到的事”。","example":"今日からまた、日本語の勉強をがんばろう！（从今天起，再好好学日语吧！）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"原作 MISSION:7","speaker":"ヨル・フォージャー","chunks":["私に","できることを","精一杯","がんばろう！"],"verify":true,"id":119},{"jp":"こんな平和が、ずっとずっと続けばいいですね","ruby":"こんな<ruby>平和<rt>へいわ</rt></ruby>が、ずっとずっと<ruby>続<rt>つづ</rt></ruby>けばいいですね","romaji":"Konna heiwa ga, zutto zutto tsuzukeba ii desu ne","zh":"要是这样平静的日子能一直一直持续下去就好了。","level":"N4","point":"「～ばいい」＝“要是……就好了”，用来表达愿望。「続く」→「続けば」：五段动词把う段换成え段再加「ば」。","example":"明日、晴れればいいですね。（明天要是晴天就好了。）","work":"SPY×FAMILY","workZh":"间谍过家家","ep":"原作 MISSION:56","speaker":"ヨル・フォージャー","chunks":["こんな平和が、","ずっとずっと","続けば","いいですね"],"verify":true,"id":120},{"jp":"もうこれで終わってもいい、だからありったけを","ruby":"もうこれで<ruby>終<rt>お</rt></ruby>わってもいい、だからありったけを","romaji":"Mō kore de owatte mo ii, dakara arittake o","zh":"就算到此为止也没关系，所以——把我的一切全都拿出来！","level":"N4","point":"「～てもいい」＝“……也可以／也没关系”，表示允许或接受。「ありったけ」＝“所有的、全部的”。","example":"疲れたら、休んでもいいよ。（累了的话，休息一下也没关系。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"ゴン＝フリークス","chunks":["もうこれで","終わってもいい、","だから","ありったけを"],"verify":true,"id":121},{"jp":"ゴン、お前にあえて本当によかった","ruby":"ゴン、お<ruby>前<rt>まえ</rt></ruby>にあえて<ruby>本当<rt>ほんとう</rt></ruby>によかった","romaji":"Gon, omae ni aete hontō ni yokatta","zh":"小杰，能遇见你真是太好了。","level":"N4","point":"「～てよかった」＝“……真是太好了”。「あえて」是「会える（能见到）」的て形，一般写作「会えて」。","example":"日本語を勉強してよかった。（学了日语真好。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"キルア＝ゾルディック","chunks":["ゴン、","お前に","あえて","本当によかった"],"verify":true,"id":122},{"jp":"これからはいちいちお礼を言ったりしない","ruby":"これからはいちいちお<ruby>礼<rt>れい</rt></ruby>を<ruby>言<rt>い</rt></ruby>ったりしない","romaji":"Kore kara wa ichiichi orei o ittari shinai","zh":"从今以后，我不会再一次次跟你道谢了。","level":"N4","point":"「～たりする」用来举例，“做……之类的事”；否定「～たりしない」带有“不会去做那种事”的语气。「いちいち」＝“每次都、一一”。","example":"夜はもう、甘いものを食べたりしない。（晚上我不会再吃甜食之类的了。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"キルア＝ゾルディック","chunks":["これからは","いちいち","お礼を","言ったりしない"],"verify":true,"id":123},{"jp":"もう…仲間を失うのは、絶対にイヤだ！","ruby":"もう…<ruby>仲間<rt>なかま</rt></ruby>を<ruby>失<rt>うしな</rt></ruby>うのは、<ruby>絶対<rt>ぜったい</rt></ruby>にイヤだ！","romaji":"Mō... nakama o ushinau no wa, zettai ni iya da!","zh":"我再也……绝对不想失去同伴了！","level":"N4","point":"「动词＋のは」把动作变成名词当主语，“……这件事”。「イヤだ」＝“讨厌、不愿意”，也写作「嫌だ」。","example":"朝早く起きるのは苦手です。（我不擅长早起。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"クラピカ","chunks":["もう…","仲間を","失うのは、","絶対にイヤだ！"],"verify":true,"id":124},{"jp":"あまり強い言葉を遣うなよ。弱く見えるぞ","ruby":"あまり<ruby>強<rt>つよ</rt></ruby>い<ruby>言葉<rt>ことば</rt></ruby>を<ruby>遣<rt>つか</rt></ruby>うなよ。<ruby>弱<rt>よわ</rt></ruby>く<ruby>見<rt>み</rt></ruby>えるぞ","romaji":"Amari tsuyoi kotoba o tsukau na yo. Yowaku mieru zo","zh":"别老说那么狠的话，会显得你很弱哦。","level":"N4","point":"「形容词く＋見える」＝“看起来……”。「动词原形＋な」是禁止，“别……”，语气很冲，日常用「～ないで」更柔和。「遣う」一般写作「使う」。","example":"この服を着ると、若く見えるね。（穿这件衣服显得很年轻呢。）","work":"BLEACH","workZh":"死神","ep":"","speaker":"藍染惣右介","chunks":["あまり","強い言葉を","遣うなよ。","弱く見えるぞ"],"verify":true,"id":125},{"jp":"いつかきっと返しに来い、立派な海賊になってな","ruby":"いつかきっと<ruby>返<rt>かえ</rt></ruby>しに<ruby>来<rt>こ</rt></ruby>い、<ruby>立派<rt>りっぱ</rt></ruby>な<ruby>海賊<rt>かいぞく</rt></ruby>になってな","romaji":"Itsuka kitto kaeshi ni koi, rippa na kaizoku ni natte na","zh":"总有一天一定要来还给我，等你成了了不起的海盗。","level":"N4","point":"「动词ます形＋に来る」＝“来做……”，「返しに来い」＝“来还”，「来い」是「来る」的命令形。句末「～てな」是轻松的叮嘱。","example":"今度、うちに遊びに来てね。（下次来我家玩吧。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"シャンクス","chunks":["いつかきっと","返しに来い、","立派な海賊に","なってな"],"verify":true,"id":126},{"jp":"礼を言う、おれはまだまだ強くなれる","ruby":"<ruby>礼<rt>れい</rt></ruby>を<ruby>言<rt>い</rt></ruby>う、おれはまだまだ<ruby>強<rt>つよ</rt></ruby>くなれる","romaji":"Rei o iu, ore wa mada mada tsuyoku nareru","zh":"谢了，我还能变得更强。","level":"N4","point":"「まだまだ」＝“还远远（没到头）”，和可能形「なれる」连用就是“还能更……”。「礼を言う」是比较郑重、硬朗的道谢说法。","example":"練習すれば、まだまだ速く走れる。（练习的话，还能跑得更快。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"ロロノア・ゾロ","chunks":["礼を言う、","おれは","まだまだ","強くなれる"],"verify":true,"id":127},{"jp":"いつかまた会えたら、もう一度仲間と呼んでくれますか！？","ruby":"いつかまた<ruby>会<rt>あ</rt></ruby>えたら、もう<ruby>一度<rt>いちど</rt></ruby><ruby>仲間<rt>なかま</rt></ruby>と<ruby>呼<rt>よ</rt></ruby>んでくれますか！？","romaji":"Itsuka mata aetara, mō ichido nakama to yonde kuremasu ka!?","zh":"如果有一天还能再见，你们还愿意再叫我一声同伴吗？","level":"N4","point":"「会えたら」＝可能形「会える」＋「たら」，“如果能见到的话”。「～てくれますか」是礼貌地请对方为自己做某事。","example":"時間があったら、手伝ってくれますか。（有时间的话，能帮我一下吗？）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"ネフェルタリ・ビビ","chunks":["いつかまた","会えたら、","もう一度","仲間と","呼んでくれますか！？"],"verify":true,"id":128},{"jp":"オレがしりてェのは楽な道のりじゃねェ、険しい道の歩き方だ","ruby":"オレがしりてェのは<ruby>楽<rt>らく</rt></ruby>な<ruby>道<rt>みち</rt></ruby>のりじゃねェ、<ruby>険<rt>けわ</rt></ruby>しい<ruby>道<rt>みち</rt></ruby>の<ruby>歩<rt>ある</rt></ruby>き<ruby>方<rt>かた</rt></ruby>だ","romaji":"Ore ga shiritee no wa raku na michinori ja nee, kewashii michi no arukikata da","zh":"我想知道的不是轻松的路，而是怎么走艰险的路。","level":"N4","point":"「しりてェ」「じゃねェ」是「知りたい」「じゃない」的粗犷口语。「～のはAじゃない、Bだ」＝“……的不是A，而是B”。「ます形＋方」＝“……的方法”。","example":"私が知りたいのは、おいしいカレーの作り方です。（我想知道的是好吃咖喱的做法。）","work":"NARUTO -ナルト-","workZh":"火影忍者","ep":"","speaker":"うずまきナルト","chunks":["オレがしりてェのは","楽な道のりじゃねェ、","険しい道の","歩き方だ"],"verify":true,"id":129},{"jp":"だからこれからも沢山見せてね、ぼっちちゃんのロック！","ruby":"だからこれからも<ruby>沢山<rt>たくさん</rt></ruby><ruby>見<rt>み</rt></ruby>せてね、ぼっちちゃんのロック！","romaji":"Dakara kore kara mo takusan misete ne, Botchi-chan no rokku!","zh":"所以以后也要让我多看看哦，小孤独的摇滚！","level":"N4","point":"「～てね」是亲切的请求，“要……哦”，朋友之间常用。「見せる」＝“给别人看”，别和「見る（看）」搞混。","example":"着いたら連絡してね。（到了要联系我哦。）","work":"ぼっち・ざ・ろっく！","workZh":"孤独摇滚！","ep":"","speaker":"伊地知虹夏","chunks":["だから","これからも","沢山見せてね、","ぼっちちゃんのロック！"],"verify":true,"id":130},{"jp":"バンドって第2の家族って感じしない？","ruby":"バンドって<ruby>第<rt>だい</rt></ruby>2の<ruby>家族<rt>かぞく</rt></ruby>って<ruby>感<rt>かん</rt></ruby>じしない？","romaji":"Bando tte daini no kazoku tte kanji shinai?","zh":"你不觉得乐队就像第二个家吗？","level":"N4","point":"「～って感じ（が）しない？」＝“不觉得有……的感觉吗？”，年轻人聊天很常用。第一个「って」相当于「は」，第二个「って」相当于「という」。","example":"この曲って、夏って感じしない？（这首歌是不是很有夏天的感觉？）","work":"ぼっち・ざ・ろっく！","workZh":"孤独摇滚！","ep":"","speaker":"喜多郁代","chunks":["バンドって","第2の家族って","感じしない？"],"verify":true,"id":131},{"jp":"もう少し続けてみたら、そのギターにふさわしい人になれるかもよ？","ruby":"もう<ruby>少<rt>すこ</rt></ruby>し<ruby>続<rt>つづ</rt></ruby>けてみたら、そのギターにふさわしい<ruby>人<rt>ひと</rt></ruby>になれるかもよ？","romaji":"Mō sukoshi tsuzukete mitara, sono gitā ni fusawashii hito ni nareru kamo yo?","zh":"再坚持一阵试试的话，说不定就能成为配得上那把吉他的人哦？","level":"N4","point":"「～てみたら」＝“试着……的话”，常用来委婉地给建议。「かも」是「かもしれない」的口语省略，“说不定”。","example":"一度先生に聞いてみたら？（要不去问问老师试试？）","work":"ぼっち・ざ・ろっく！","workZh":"孤独摇滚！","ep":"","speaker":"廣井きくり","chunks":["もう少し","続けてみたら、","そのギターに","ふさわしい人に","なれるかもよ？"],"verify":true,"id":132},{"jp":"お前のことちゃんと見てるからな","ruby":"お<ruby>前<rt>まえ</rt></ruby>のことちゃんと<ruby>見<rt>み</rt></ruby>てるからな","romaji":"Omae no koto chanto miteru kara na","zh":"我可是一直好好看着你的。","level":"N4","point":"「見てる」＝「見ている」，表示一直在看着的状态。人名后加「のこと」，如「お前のこと見てる」，比「お前を見てる」多一层关心的感觉。","example":"みんな、あなたのこと応援してるよ。（大家都在支持你哦。）","work":"ぼっち・ざ・ろっく！","workZh":"孤独摇滚！","ep":"","speaker":"伊地知星歌","chunks":["お前のこと","ちゃんと","見てるからな"],"verify":true,"id":133},{"jp":"アイドルがアイドルでいられる時間は長くない","ruby":"アイドルがアイドルでいられる<ruby>時間<rt>じかん</rt></ruby>は<ruby>長<rt>なが</rt></ruby>くない","romaji":"Aidoru ga aidoru de irareru jikan wa nagakunai","zh":"偶像能一直当偶像的时间并不长。","level":"N4","point":"「～でいる」＝“保持……的状态”，可能形「でいられる」＝“能一直是……”。一段动词的可能形是去掉「る」加「られる」。","example":"いつまでも友達でいられたらいいな。（要是能一直做朋友就好了。）","work":"【推しの子】","workZh":"我推的孩子","ep":"","speaker":"星野ルビー","chunks":["アイドルが","アイドルでいられる","時間は","長くない"],"verify":true,"id":134},{"jp":"私は何があってもアクアくんの味方だよ","ruby":"<ruby>私<rt>わたし</rt></ruby>は<ruby>何<rt>なに</rt></ruby>があってもアクアくんの<ruby>味方<rt>みかた</rt></ruby>だよ","romaji":"Watashi wa nani ga atte mo Akua-kun no mikata da yo","zh":"无论发生什么，我都站在阿库亚这边。","level":"N4","point":"「疑问词＋ても」表示“不管……都”，「何があっても」＝“无论发生什么”。「～の味方」＝“站在……这一边”。","example":"何があっても、私は君を信じるよ。（无论发生什么，我都相信你。）","work":"【推しの子】","workZh":"我推的孩子","ep":"","speaker":"黒川あかね","chunks":["私は","何があっても","アクアくんの","味方だよ"],"verify":true,"id":135},{"jp":"何もできないまま終わる人生もあるんだよ","ruby":"<ruby>何<rt>なに</rt></ruby>もできないまま<ruby>終<rt>お</rt></ruby>わる<ruby>人生<rt>じんせい</rt></ruby>もあるんだよ","romaji":"Nani mo dekinai mama owaru jinsei mo aru n da yo","zh":"也有那种什么都没做成就结束了的人生啊。","level":"N4","point":"「～まま」＝“保持着……的状态（就……）”，「できないまま」＝“一直没能做成就……”。「何も～ない」＝“什么都不……”。","example":"窓を開けたまま寝てしまった。（开着窗就睡着了。）","work":"【推しの子】","workZh":"我推的孩子","ep":"","speaker":"星野ルビー","chunks":["何もできないまま","終わる人生も","あるんだよ"],"verify":true,"id":136},{"jp":"ずっと何か、誰かを探している","ruby":"ずっと<ruby>何<rt>なに</rt></ruby>か、<ruby>誰<rt>だれ</rt></ruby>かを<ruby>探<rt>さが</rt></ruby>している","romaji":"Zutto nanika, dareka o sagashite iru","zh":"一直在寻找着什么，寻找着某个人。","level":"N4","point":"「～ている」表示动作一直在持续，“正在……／一直在……”。「何か」「誰か」＝“某样东西”“某个人”。","example":"駅の前で友達を待っている。（我在车站前等朋友。）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"","chunks":["ずっと","何か、","誰かを","探している"],"verify":true,"id":137},{"jp":"私たちは会えば絶対すぐに分かる","ruby":"<ruby>私<rt>わたし</rt></ruby>たちは<ruby>会<rt>あ</rt></ruby>えば<ruby>絶対<rt>ぜったい</rt></ruby>すぐに<ruby>分<rt>わ</rt></ruby>かる","romaji":"Watashitachi wa aeba zettai sugu ni wakaru","zh":"我们只要见了面，一定马上就能认出彼此。","level":"N4","point":"「～ば」是条件形，“只要……就……”。「会う」→「会えば」：五段动词把う段换成え段再加「ば」。","example":"地図を見れば、すぐ分かりますよ。（看一下地图马上就明白了。）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"宮水三葉","chunks":["私たちは","会えば","絶対","すぐに分かる"],"verify":true,"id":138},{"jp":"言おうと思ったんだ、お前がどこの世界にいても、俺が必ずもう一度会いに行くって","ruby":"<ruby>言<rt>い</rt></ruby>おうと<ruby>思<rt>おも</rt></ruby>ったんだ、お<ruby>前<rt>まえ</rt></ruby>がどこの<ruby>世界<rt>せかい</rt></ruby>にいても、<ruby>俺<rt>おれ</rt></ruby>が<ruby>必<rt>かなら</rt></ruby>ずもう<ruby>一度<rt>いちど</rt></ruby><ruby>会<rt>あ</rt></ruby>いに<ruby>行<rt>い</rt></ruby>くって","romaji":"Iō to omotta n da, omae ga doko no sekai ni ite mo, ore ga kanarazu mō ichido ai ni iku tte","zh":"我本来想告诉你的：不管你在世界的哪里，我一定会再去见你。","level":"N4","point":"「意志形＋と思った」＝“（当时）想要……”，「言おうと思った」就是“本来想说”。「どこに～ても」＝“无论在哪里都……”。","example":"電話しようと思ったんだけど、忘れちゃった。（本来想打电话的，结果忘了。）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"立花瀧","chunks":["言おうと思ったんだ、","お前が","どこの世界にいても、","俺が必ず","もう一度会いに行くって"],"verify":true,"id":139},{"jp":"大事な人。忘れたくない人。忘れちゃダメな人。","ruby":"<ruby>大事<rt>だいじ</rt></ruby>な<ruby>人<rt>ひと</rt></ruby>。<ruby>忘<rt>わす</rt></ruby>れたくない<ruby>人<rt>ひと</rt></ruby>。<ruby>忘<rt>わす</rt></ruby>れちゃダメな<ruby>人<rt>ひと</rt></ruby>。","romaji":"Daiji na hito. Wasuretakunai hito. Wasurecha dame na hito.","zh":"重要的人。不想忘记的人。不能忘记的人。","level":"N4","point":"「～ちゃダメ」是「～てはダメ」的口语，“不可以……”。和「～たくない（不想……）」对比着记：一个是自己的愿望，一个是不允许。","example":"ここで写真を撮っちゃダメだよ。（这里不可以拍照哦。）","work":"君の名は。","workZh":"你的名字。","ep":"劇場版","speaker":"立花瀧","chunks":["大事な人。","忘れたくない人。","忘れちゃダメな人。"],"verify":true,"id":140},{"jp":"今も昔も俺の護るもんは、何一つ変わっちゃいねェェ！！","ruby":"<ruby>今<rt>いま</rt></ruby>も<ruby>昔<rt>むかし</rt></ruby>も<ruby>俺<rt>おれ</rt></ruby>の<ruby>護<rt>まも</rt></ruby>るもんは、<ruby>何<rt>なに</rt></ruby><ruby>一<rt>ひと</rt></ruby>つ<ruby>変<rt>か</rt></ruby>わっちゃいねェェ！！","romaji":"Ima mo mukashi mo ore no mamoru mon wa, nani hitotsu kawatcha inee!!","zh":"不管是现在还是过去，我要守护的东西一样都没变过！","level":"N4","point":"「変わっちゃいねェ」是「変わってはいない」的粗犷口语，“并没有变”；「ていない」表示变化没有发生。「もん」是「もの」的口语。平时说「何も変わっていない」就好。","example":"この町は十年前と何も変わっていない。（这个小镇和十年前相比什么都没变。）","work":"銀魂","workZh":"银魂","ep":"","speaker":"坂田銀時","chunks":["今も昔も","俺の護るもんは、","何一つ","変わっちゃいねェェ！！"],"verify":true,"id":141},{"jp":"卒業、しないでよ","ruby":"<ruby>卒業<rt>そつぎょう</rt></ruby>、しないでよ","romaji":"Sotsugyō, shinai de yo","zh":"不要毕业嘛。","level":"N4","point":"「～ないで」＝“不要……”，后面加「よ」带着撒娇、恳求的语气。更礼貌的说法是「～ないでください」。","example":"まだ帰らないでよ。（先别走嘛。）","work":"けいおん!","workZh":"轻音少女","ep":"","speaker":"中野梓","chunks":["卒業、","しないで","よ"],"verify":true,"id":142},{"jp":"生きるのを手伝ってほしい","ruby":"<ruby>生<rt>い</rt></ruby>きるのを<ruby>手伝<rt>てつだ</rt></ruby>ってほしい","romaji":"Ikiru no o tetsudatte hoshii","zh":"希望你帮我好好活下去。","level":"N4","point":"「（人に）～てほしい」＝“希望别人做……”，表达对别人的愿望。动词后加「の」能把它变成名词，「生きるのを」＝“活下去这件事”。","example":"この荷物を運ぶのを手伝ってほしい。（希望你帮我搬一下这个行李。）","work":"聲の形","workZh":"声之形","ep":"","speaker":"石田将也","chunks":["生きるのを","手伝って","ほしい"],"verify":true,"id":143},{"jp":"おれも、優しくなりたいって思ったんだ","ruby":"おれも、<ruby>優<rt>やさ</rt></ruby>しくなりたいって<ruby>思<rt>おも</rt></ruby>ったんだ","romaji":"Ore mo, yasashiku naritai tte omotta n da","zh":"我也想要变得温柔。","level":"N4","point":"「形容词く＋なりたい」＝“想变得……”。「～って思った」是「～と思った」的口语说法。","example":"もっと強くなりたいって思った。（我想要变得更强。）","work":"夏目友人帳","workZh":"夏目友人帐","ep":"","speaker":"夏目貴志","chunks":["おれも、","優しくなりたいって","思ったんだ"],"verify":true,"id":144},{"jp":"しっかりしろ夏目。つかなくていい嘘はつくな","ruby":"しっかりしろ<ruby>夏目<rt>なつめ</rt></ruby>。つかなくていい<ruby>嘘<rt>うそ</rt></ruby>はつくな","romaji":"Shikkari shiro Natsume. Tsukanakute ii uso wa tsuku na","zh":"振作点，夏目。没必要撒的谎就别撒。","level":"N4","point":"「～なくていい」＝“不必……”。「嘘をつく」＝“说谎”，是固定搭配；「つくな」是禁止形，“别……”。","example":"明日は来なくていいですよ。（明天不用来了。）","work":"夏目友人帳","workZh":"夏目友人帐","ep":"","speaker":"田沼要","chunks":["しっかりしろ夏目。","つかなくていい","嘘は","つくな"],"verify":true,"id":145},{"jp":"これは私がやってみたくてやっていることなの","ruby":"これは<ruby>私<rt>わたし</rt></ruby>がやってみたくてやっていることなの","romaji":"Kore wa watashi ga yatte mitakute yatte iru koto na no","zh":"这是我自己想试试才去做的事。","level":"N4","point":"「～てみたい」＝“想试试……”，变成「～てみたくて」就表示原因：“因为想试试，所以……”。","example":"一度行ってみたくて、京都に来ました。（一直想去一次，所以来了京都。）","work":"夏目友人帳","workZh":"夏目友人帐","ep":"","speaker":"夏目レイコ","chunks":["これは","私が","やってみたくて","やっていることなの"],"verify":true,"id":146},{"jp":"私はもうちょっと西片の隣の席がよかったなぁ","ruby":"<ruby>私<rt>わたし</rt></ruby>はもうちょっと<ruby>西片<rt>にしかた</rt></ruby>の<ruby>隣<rt>となり</rt></ruby>の<ruby>席<rt>せき</rt></ruby>がよかったなぁ","romaji":"Watashi wa mō chotto Nishikata no tonari no seki ga yokatta nā","zh":"我还想再多坐一阵西片旁边的位子呢。","level":"N4","point":"「～がよかった」＝“（要是）……就好了”，对已经定下的事表示遗憾或愿望。「もうちょっと」＝“再稍微……”。","example":"私は窓側の席がよかったなぁ。（我还是想坐靠窗的位子啊。）","work":"からかい上手の高木さん","workZh":"擅长捉弄人的高木同学","ep":"原作第3巻","speaker":"高木さん","chunks":["私は","もうちょっと","西片の隣の席が","よかったなぁ"],"verify":true,"id":147},{"jp":"今日はエイプリルフールだからだまそうと思ったんでしょ","ruby":"<ruby>今日<rt>きょう</rt></ruby>はエイプリルフールだからだまそうと<ruby>思<rt>おも</rt></ruby>ったんでしょ","romaji":"Kyō wa eipuriru fūru dakara damasō to omotta n desho","zh":"因为今天是愚人节，所以你想骗我，对吧？","level":"N4","point":"「意志形＋と思う」＝“打算……”。句末「～んでしょ」用来确认、看穿对方的心思，“……对吧？”。","example":"明日は休みだから、遅くまで寝ようと思ってるんでしょ。（明天放假，你打算睡懒觉对吧？）","work":"からかい上手の高木さん","workZh":"擅长捉弄人的高木同学","ep":"原作第10巻","speaker":"高木さん","chunks":["今日は","エイプリルフールだから","だまそうと","思ったんでしょ"],"verify":true,"id":148},{"jp":"せっかく晴れたし寄り道して帰ろう","ruby":"せっかく<ruby>晴<rt>は</rt></ruby>れたし<ruby>寄<rt>よ</rt></ruby>り<ruby>道<rt>みち</rt></ruby>して<ruby>帰<rt>かえ</rt></ruby>ろう","romaji":"Sekkaku hareta shi yorimichi shite kaerō","zh":"难得放晴了，我们绕个路再回家吧。","level":"N4","point":"「～し」用来说理由，“（既然）……”；「せっかく」＝“难得”。「帰ろう」是意志形，表示提议“……吧”。","example":"せっかく来たし、写真を撮ろう。（难得来一趟，拍张照吧。）","work":"からかい上手の高木さん","workZh":"擅长捉弄人的高木同学","ep":"原作第2巻","speaker":"高木さん","chunks":["せっかく","晴れたし","寄り道して","帰ろう"],"verify":true,"id":149},{"jp":"人は何かの犠牲なしに何も得ることは出来ない。","ruby":"<ruby>人<rt>ひと</rt></ruby>は<ruby>何<rt>なに</rt></ruby>かの<ruby>犠牲<rt>ぎせい</rt></ruby>なしに<ruby>何<rt>なに</rt></ruby>も<ruby>得<rt>え</rt></ruby>ることは<ruby>出来<rt>でき</rt></ruby>ない。","romaji":"Hito wa nanika no gisei nashi ni nani mo eru koto wa dekinai.","zh":"人不付出某种牺牲，就什么也得不到。","level":"N1","point":"「名词＋なしに」＝“没有……就（不能）……”，是「～なしで」「～ないで」的书面说法，后面多接否定。","example":"努力なしに成功はありえない。（没有努力就不可能成功。）","work":"鋼の錬金術師","workZh":"钢之炼金术师","ep":"","speaker":"","chunks":["人は","何かの犠牲なしに","何も","得ることは","出来ない。"],"verify":true,"id":150},{"jp":"曇りなき眼で見定め、決める","ruby":"<ruby>曇<rt>くも</rt></ruby>りなき<ruby>眼<rt>まなこ</rt></ruby>で<ruby>見定<rt>みさだ</rt></ruby>め、<ruby>決<rt>き</rt></ruby>める","romaji":"Kumori naki manako de misadame, kimeru.","zh":"用毫无阴霾的双眼看清，再做决定。","level":"N1","point":"「なき」是文语「なし」的连体形，等于现代的「ない」，「曇りなき眼」就是“没有阴霾的眼睛”。「見定め、」是动词连用形中顿，书面语里用来连接动作。","example":"悔いなき人生を送りたい。（想过无悔的人生。）","work":"もののけ姫","workZh":"幽灵公主","ep":"劇場版","speaker":"アシタカ","chunks":["曇りなき","眼で","見定め、","決める"],"verify":true,"id":151},{"jp":"天地の間にあるすべてのものを欲するは人の業というものだ","ruby":"<ruby>天地<rt>てんち</rt></ruby>の<ruby>間<rt>あいだ</rt></ruby>にあるすべてのものを<ruby>欲<rt>ほっ</rt></ruby>するは<ruby>人<rt>ひと</rt></ruby>の<ruby>業<rt>ごう</rt></ruby>というものだ","romaji":"Tenchi no aida ni aru subete no mono o hossuru wa hito no gō to iu mono da.","zh":"想要天地之间的一切，这就是人的业。","level":"N1","point":"「欲するは」是文语用法，动词连体形直接接「は」当名词（现代说「欲するのは」）；「～というものだ」表示“这就是所谓的……”，带断定语气。","example":"約束を守らないのは、無責任というものだ。（不守约就是不负责任。）","work":"もののけ姫","workZh":"幽灵公主","ep":"劇場版","speaker":"ジコ坊","chunks":["天地の間にある","すべてのものを","欲するは","人の業と","いうものだ"],"verify":true,"id":152},{"jp":"わからぬ。だがともに生きることは出来る","ruby":"わからぬ。だがともに<ruby>生<rt>い</rt></ruby>きることは<ruby>出来<rt>でき</rt></ruby>る","romaji":"Wakaranu. Daga tomo ni ikiru koto wa dekiru.","zh":"我不知道。但我们可以一起活下去。","level":"N1","point":"「ぬ」是文语否定助动词，「わからぬ」＝「わからない」，古装、武士类角色常用。「だが」是偏书面、偏男性的“但是”。","example":"知らぬ間に雨が止んでいた。（不知不觉雨已经停了。）","work":"もののけ姫","workZh":"幽灵公主","ep":"劇場版","speaker":"アシタカ","chunks":["わからぬ。","だが","ともに生きることは","出来る"],"verify":true,"id":153},{"jp":"雷神の少し響みてさし曇り雨も降らぬか君を留めむ","ruby":"<ruby>雷神<rt>なるかみ</rt></ruby>の<ruby>少<rt>すこ</rt></ruby>し<ruby>響<rt>とよ</rt></ruby>みてさし<ruby>曇<rt>ぐも</rt></ruby>り<ruby>雨<rt>あめ</rt></ruby>も<ruby>降<rt>ふ</rt></ruby>らぬか<ruby>君<rt>きみ</rt></ruby>を<ruby>留<rt>とど</rt></ruby>めむ","romaji":"Narukami no sukoshi toyomite sashigumori ame mo furanu ka kimi o todomemu.","zh":"隐隐雷声响，天色暗下来，雨若能落下，便可留住你。","level":"N1","point":"这是《万叶集》里的和歌。「降らぬか」＝“不下点雨吗”，表示盼望；「留めむ」的「む」是文语的意志助动词，相当于现代的「～よう」。了解即可，现代口语不这么说。","example":"雨が降ればいいのに。そうしたら君を引き留められる。（要是下雨就好了，那样就能留住你。）","work":"言の葉の庭","workZh":"言叶之庭","ep":"劇場版","speaker":"雪野百香里","chunks":["雷神の","少し響みて","さし曇り","雨も降らぬか","君を留めむ"],"verify":true,"id":154},{"jp":"ラピュタは滅びぬ。何度でも蘇るさ。","ruby":"ラピュタは<ruby>滅<rt>ほろ</rt></ruby>びぬ。<ruby>何度<rt>なんど</rt></ruby>でも<ruby>蘇<rt>よみがえ</rt></ruby>るさ。","romaji":"Rapyuta wa horobinu. Nando demo yomigaeru sa.","zh":"拉普达是不会灭亡的。无论多少次都会复活。","level":"N1","point":"「滅びぬ」的「ぬ」是文语否定，＝「滅びない」，听起来庄重又傲慢；「何度でも」是“疑问词＋でも”，表示“无论多少次”。","example":"わからないことがあれば、何度でも聞いてね。（有不懂的，问多少次都行。）","work":"天空の城ラピュタ","workZh":"天空之城","ep":"劇場版","speaker":"ムスカ","chunks":["ラピュタは","滅びぬ。","何度でも","蘇るさ。"],"verify":true,"id":155},{"jp":"生殺与奪の権を他人に握らせるな！！","ruby":"<ruby>生殺与奪<rt>せいさつよだつ</rt></ruby>の<ruby>権<rt>けん</rt></ruby>を<ruby>他人<rt>たにん</rt></ruby>に<ruby>握<rt>にぎ</rt></ruby>らせるな！！","romaji":"Seisatsu yodatsu no ken o tanin ni nigiraseru na!!","zh":"不要把生杀予夺的权力交给别人！！","level":"N1","point":"「生殺与奪の権」是四字熟语，“生杀予夺之权”。「握らせるな」＝使役形「握らせる」＋禁止「な」，意思是“别让别人掌握”。","example":"子供に危ない物を持たせるな。（别让孩子拿危险的东西。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"第1話","speaker":"冨岡義勇","chunks":["生殺与奪の","権を","他人に","握らせるな！！"],"verify":true,"id":156},{"jp":"お前のその実力は柱に届くと言っても過言ではない","ruby":"お<ruby>前<rt>まえ</rt></ruby>のその<ruby>実力<rt>じつりょく</rt></ruby>は<ruby>柱<rt>はしら</rt></ruby>に<ruby>届<rt>とど</rt></ruby>くと<ruby>言<rt>い</rt></ruby>っても<ruby>過言<rt>かごん</rt></ruby>ではない","romaji":"Omae no sono jitsuryoku wa hashira ni todoku to itte mo kagon de wa nai.","zh":"说你的实力已经够得上“柱”也不为过。","level":"N1","point":"「～と言っても過言ではない」＝“说……也不为过”，书面语，评价、演讲里很常见。","example":"スマホは現代人の必需品と言っても過言ではない。（说手机是现代人的必需品也不为过。）","work":"鬼滅の刃","workZh":"鬼灭之刃","ep":"","speaker":"冨岡義勇","chunks":["お前のその実力は","柱に届くと","言っても","過言ではない"],"verify":true,"id":157},{"jp":"俺は一度としてお前達を家来だと思ったことはねェ。士道の名の下、俺達ゃ五分の同志だ","ruby":"<ruby>俺<rt>おれ</rt></ruby>は<ruby>一度<rt>いちど</rt></ruby>としてお<ruby>前達<rt>まえたち</rt></ruby>を<ruby>家来<rt>けらい</rt></ruby>だと<ruby>思<rt>おも</rt></ruby>ったことはねェ。<ruby>士道<rt>しどう</rt></ruby>の<ruby>名<rt>な</rt></ruby>の<ruby>下<rt>もと</rt></ruby>、<ruby>俺達<rt>おれたち</rt></ruby>ゃ<ruby>五分<rt>ごぶ</rt></ruby>の<ruby>同志<rt>どうし</rt></ruby>だ","romaji":"Ore wa ichido to shite omaetachi o kerai da to omotta koto wa nee. Shidō no na no moto, oretachi ya gobu no dōshi da.","zh":"我从来没把你们当成手下。在士道之名下，我们是平起平坐的同志。","level":"N1","point":"「一度として～ない」＝“一次也没有……”，强调全面否定；「～の名の下（に）」＝“以……之名”。「ねェ」「俺達ゃ」是粗犷口语，平时说「ない」「俺たちは」。","example":"彼は一度として約束を破ったことがない。（他一次也没失约过。）","work":"銀魂","workZh":"银魂","ep":"","speaker":"近藤勲","chunks":["俺は一度として","お前達を家来だと","思ったことはねェ。","士道の名の下、","俺達ゃ五分の同志だ"],"verify":true,"id":158},{"jp":"一度あったことは忘れないものさ。思い出せないだけで","ruby":"<ruby>一度<rt>いちど</rt></ruby>あったことは<ruby>忘<rt>わす</rt></ruby>れないものさ。<ruby>思<rt>おも</rt></ruby>い<ruby>出<rt>だ</rt></ruby>せないだけで","romaji":"Ichido atta koto wa wasurenai mono sa. Omoidasenai dake de.","zh":"发生过一次的事是不会忘记的，只是想不起来而已。","level":"N2","point":"「～ものだ（口语「ものさ」）」表示事物的本性或普遍道理，“本来就是……”。后半句「思い出せないだけで」是倒装补充，省略了后面的话。","example":"子供はすぐ大きくなるものだ。（孩子总是一转眼就长大了。）","work":"千と千尋の神隠し","workZh":"千与千寻","ep":"劇場版","speaker":"銭婆","chunks":["一度あったことは","忘れないものさ。","思い出せない","だけで"],"verify":true,"id":159},{"jp":"僕は本当は臆病者なんだ。怖くて怖くてたまらない……","ruby":"<ruby>僕<rt>ぼく</rt></ruby>は<ruby>本当<rt>ほんとう</rt></ruby>は<ruby>臆病者<rt>おくびょうもの</rt></ruby>なんだ。<ruby>怖<rt>こわ</rt></ruby>くて<ruby>怖<rt>こわ</rt></ruby>くてたまらない……","romaji":"Boku wa hontō wa okubyōmono nan da. Kowakute kowakute tamaranai...","zh":"其实我是个胆小鬼。害怕得不得了……","level":"N2","point":"「～てたまらない」＝“……得受不了、……得不得了”，表示情绪或感觉强烈到压不住；重复「怖くて怖くて」更加强调。","example":"試験の結果が気になってたまらない。（特别在意考试结果。）","work":"ハウルの動く城","workZh":"哈尔的移动城堡","ep":"劇場版","speaker":"ハウル","chunks":["僕は本当は","臆病者なんだ。","怖くて怖くて","たまらない……"],"verify":true,"id":160},{"jp":"だけど不自由である事と不幸である事はイコールじゃない","ruby":"だけど<ruby>不自由<rt>ふじゆう</rt></ruby>である<ruby>事<rt>こと</rt></ruby>と<ruby>不幸<rt>ふこう</rt></ruby>である<ruby>事<rt>こと</rt></ruby>はイコールじゃない","romaji":"Dakedo fujiyū de aru koto to fukō de aru koto wa ikōru ja nai.","zh":"可是，不自由和不幸并不能画等号。","level":"N2","point":"「～である」是「～だ」的书面形式，「な形容词/名词＋である事」可以把一种状态变成名词来讨论。","example":"健康である事が何より大切だ。（健康比什么都重要。）","work":"鋼の錬金術師","workZh":"钢之炼金术师","ep":"","speaker":"アルフォンス・エルリック","chunks":["だけど","不自由である事と","不幸である事は","イコールじゃない"],"verify":true,"id":161},{"jp":"必死に生きてきた人の行きつく先が無であっていいはずがありません。","ruby":"<ruby>必死<rt>ひっし</rt></ruby>に<ruby>生<rt>い</rt></ruby>きてきた<ruby>人<rt>ひと</rt></ruby>の<ruby>行<rt>い</rt></ruby>きつく<ruby>先<rt>さき</rt></ruby>が<ruby>無<rt>む</rt></ruby>であっていいはずがありません。","romaji":"Hisshi ni ikite kita hito no ikitsuku saki ga mu de atte ii hazu ga arimasen.","zh":"拼命活过来的人，最后的归宿不可能是一片虚无。","level":"N2","point":"「～ていいはずがない」＝“绝不应该……”，「はずがない」表示说话人坚信“不可能”，这里语气很强；「無であって」是「無である」的て形。","example":"こんな不公平が許されていいはずがない。（这种不公平不可能被允许。）","work":"葬送のフリーレン","workZh":"葬送的芙莉莲","ep":"第4話","speaker":"ハイター","chunks":["必死に生きてきた人の","行きつく先が","無であって","いいはずがありません。"],"verify":true,"id":162},{"jp":"相手に貸しを作ってしまったら本当の意味で助けたことにはならないだろう。","ruby":"<ruby>相手<rt>あいて</rt></ruby>に<ruby>貸<rt>か</rt></ruby>しを<ruby>作<rt>つく</rt></ruby>ってしまったら<ruby>本当<rt>ほんとう</rt></ruby>の<ruby>意味<rt>いみ</rt></ruby>で<ruby>助<rt>たす</rt></ruby>けたことにはならないだろう。","romaji":"Aite ni kashi o tsukutte shimattara hontō no imi de tasuketa koto ni wa naranai darō.","zh":"要是让对方欠了人情，就不算真正意义上的帮助了吧。","level":"N2","point":"「～たことにはならない」＝“不能算是……”；「貸しを作る」是“让对方欠自己人情”的固定说法。","example":"一回読んだだけでは、勉強したことにはならない。（只读一遍可不算学过。）","work":"葬送のフリーレン","workZh":"葬送的芙莉莲","ep":"","speaker":"ヒンメル","chunks":["相手に貸しを","作ってしまったら","本当の意味で","助けたことには","ならないだろう。"],"verify":true,"id":163},{"jp":"逆境でこそそいつが本物かどうかわかる。","ruby":"<ruby>逆境<rt>ぎゃっきょう</rt></ruby>でこそそいつが<ruby>本物<rt>ほんもの</rt></ruby>かどうかわかる。","romaji":"Gyakkyō de koso soitsu ga honmono ka dō ka wakaru.","zh":"正是在逆境里，才看得出那家伙是不是真货。","level":"N2","point":"「～でこそ」＝“正是在……才……”，强调只有在这个条件下才成立；「～かどうか」＝“是否……”。","example":"困った時にこそ、本当の友達がわかる。（正是困难的时候，才知道谁是真朋友。）","work":"四月は君の嘘","workZh":"四月是你的谎言","ep":"","speaker":"渡亮太","chunks":["逆境でこそ","そいつが","本物かどうか","わかる。"],"verify":true,"id":164},{"jp":"僕らは誰かと出会った瞬間から、一人ではいられないんだ。","ruby":"<ruby>僕<rt>ぼく</rt></ruby>らは<ruby>誰<rt>だれ</rt></ruby>かと<ruby>出会<rt>であ</rt></ruby>った<ruby>瞬間<rt>しゅんかん</rt></ruby>から、<ruby>一人<rt>ひとり</rt></ruby>ではいられないんだ。","romaji":"Bokura wa dareka to deatta shunkan kara, hitori de wa irarenai n da.","zh":"我们从与某人相遇的那一刻起，就再也不能独自一人了。","level":"N2","point":"「～ではいられない」＝“不能再保持……的状态”，表示情况已经不允许原样下去。","example":"もう子供ではいられない。（不能再当小孩子了。）","work":"四月は君の嘘","workZh":"四月是你的谎言","ep":"","speaker":"","chunks":["僕らは","誰かと出会った","瞬間から、","一人では","いられないんだ。"],"verify":true,"id":165},{"jp":"新世界の神となる","ruby":"<ruby>新世界<rt>しんせかい</rt></ruby>の<ruby>神<rt>かみ</rt></ruby>となる","romaji":"Shin sekai no kami to naru.","zh":"我要成为新世界的神。","level":"N2","point":"「～となる」比「～になる」更书面、更庄重，常用于宣言或正式场合。","example":"彼は二十歳で社長となった。（他二十岁就当上了社长。）","work":"DEATH NOTE","workZh":"死亡笔记","ep":"","speaker":"夜神月","chunks":["新世界の","神と","なる"],"verify":true,"id":166},{"jp":"世界とは己の心を映す鏡だ。","ruby":"<ruby>世界<rt>せかい</rt></ruby>とは<ruby>己<rt>おのれ</rt></ruby>の<ruby>心<rt>こころ</rt></ruby>を<ruby>映<rt>うつ</rt></ruby>す<ruby>鏡<rt>かがみ</rt></ruby>だ。","romaji":"Sekai to wa onore no kokoro o utsusu kagami da.","zh":"世界就是映照自己内心的镜子。","level":"N2","point":"「AとはBだ」用来下定义，“所谓A就是B”，带书面色彩；「己」是“自己”的文雅、古风说法。","example":"友達とは、困った時に助け合える人のことだ。（所谓朋友，就是困难时能互相帮助的人。）","work":"銀魂","workZh":"银魂","ep":"","speaker":"","chunks":["世界とは","己の心を","映す","鏡だ。"],"verify":true,"id":167},{"jp":"その人を知りたければその人が何に対して怒りを感じるかを知れ","ruby":"その<ruby>人<rt>ひと</rt></ruby>を<ruby>知<rt>し</rt></ruby>りたければその<ruby>人<rt>ひと</rt></ruby>が<ruby>何<rt>なに</rt></ruby>に<ruby>対<rt>たい</rt></ruby>して<ruby>怒<rt>いか</rt></ruby>りを<ruby>感<rt>かん</rt></ruby>じるかを<ruby>知<rt>し</rt></ruby>れ","romaji":"Sono hito o shiritakereba sono hito ga nani ni taishite ikari o kanjiru ka o shire.","zh":"想了解一个人，就去了解他会对什么感到愤怒。","level":"N2","point":"「～に対して」＝“对于、针对”；「知りたければ」是「たい」的ば形，“如果想……”；「知れ」是命令形。","example":"先生に対して失礼なことを言ってはいけない。（不能对老师说失礼的话。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"ゴン","chunks":["その人を知りたければ","その人が","何に対して","怒りを感じるかを","知れ"],"verify":true,"id":168},{"jp":"だって長く待てば待つほど逢えた時に嬉しいじゃない","ruby":"だって<ruby>長<rt>なが</rt></ruby>く<ruby>待<rt>ま</rt></ruby>てば<ruby>待<rt>ま</rt></ruby>つほど<ruby>逢<rt>あ</rt></ruby>えた<ruby>時<rt>とき</rt></ruby>に<ruby>嬉<rt>うれ</rt></ruby>しいじゃない","romaji":"Datte nagaku mateba matsu hodo aeta toki ni ureshii ja nai.","zh":"因为等得越久，见到的时候就越开心嘛。","level":"N2","point":"「～ば～ほど」＝“越……越……”，前后用同一个词；句尾「じゃない」读升调，是“不是吗”，用来寻求认同。","example":"日本語は勉強すればするほど面白くなる。（日语越学越有意思。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"毛利蘭","chunks":["だって","長く待てば待つほど","逢えた時に","嬉しいじゃない"],"verify":true,"id":169},{"jp":"正義って言葉はね、やたらと口にだして振りかざすものじゃないの…","ruby":"<ruby>正義<rt>せいぎ</rt></ruby>って<ruby>言葉<rt>ことば</rt></ruby>はね、やたらと<ruby>口<rt>くち</rt></ruby>にだして<ruby>振<rt>ふ</rt></ruby>りかざすものじゃないの…","romaji":"Seigi tte kotoba wa ne, yatara to kuchi ni dashite furikazasu mono ja nai no...","zh":"“正义”这个词啊，不是随便挂在嘴边、拿来炫耀的东西……","level":"N2","point":"「～ものじゃない」＝“不应该……”，按常理劝诫别人别这么做；「やたらと」＝“随便、胡乱”。","example":"人の悪口を言うものじゃないよ。（不该说别人坏话哦。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"佐藤美和子","chunks":["正義って言葉はね、","やたらと","口にだして","振りかざす","ものじゃないの…"],"verify":true,"id":170},{"jp":"恋が女を美しくするのであれば","ruby":"<ruby>恋<rt>こい</rt></ruby>が<ruby>女<rt>おんな</rt></ruby>を<ruby>美<rt>うつく</rt></ruby>しくするのであれば","romaji":"Koi ga onna o utsukushiku suru no de areba.","zh":"如果恋爱真能让女人变美的话……","level":"N2","point":"「～のであれば」是「～なら」的书面说法，“如果真是……的话”，以某种说法或情况为前提往下推。","example":"参加するのであれば、早めに連絡してください。（如果要参加，请尽早联系。）","work":"薬屋のひとりごと","workZh":"药屋少女的呢喃","ep":"第3話","speaker":"猫猫","chunks":["恋が","女を","美しくする","のであれば"],"verify":true,"id":171},{"jp":"手に入れたいものほど手放すの。","ruby":"<ruby>手<rt>て</rt></ruby>に<ruby>入<rt>い</rt></ruby>れたいものほど<ruby>手放<rt>てばな</rt></ruby>すの。","romaji":"Te ni iretai mono hodo tebanasu no.","zh":"越是想得到的牌，越要放手。","level":"N2","point":"「名词＋ほど」＝“越是……越……”，是「～ば～ほど」的简化说法。","example":"忙しい人ほど時間の使い方が上手だ。（越是忙的人越会安排时间。）","work":"ちはやふる","workZh":"花牌情缘","ep":"","speaker":"綾瀬千早","chunks":["手に入れたい","ものほど","手放すの。"],"verify":true,"id":172},{"jp":"『縮まらないから』といってそれがオレが進まない理由にはならん。","ruby":"『<ruby>縮<rt>ちぢ</rt></ruby>まらないから』といってそれがオレが<ruby>進<rt>すす</rt></ruby>まない<ruby>理由<rt>りゆう</rt></ruby>にはならん。","romaji":"\"Chijimaranai kara\" to itte sore ga ore ga susumanai riyū ni wa naran.","zh":"就算“差距缩不小”，也不能成为我不前进的理由。","level":"N2","point":"「～からといって」＝“虽说……但（并不一定）”，后面多接否定；「ならん」是「ならない」的口语、老派说法。","example":"高いからといって、品質がいいとは限らない。（贵不一定质量就好。）","work":"3月のライオン","workZh":"三月的狮子","ep":"","speaker":"島田開","chunks":["『縮まらないから』といって","それが","オレが進まない","理由には","ならん。"],"verify":true,"id":173},{"jp":"プロになるということは止まらない列車に飛び乗るようなものだ。","ruby":"プロになるということは<ruby>止<rt>と</rt></ruby>まらない<ruby>列車<rt>れっしゃ</rt></ruby>に<ruby>飛<rt>と</rt></ruby>び<ruby>乗<rt>の</rt></ruby>るようなものだ。","romaji":"Puro ni naru to iu koto wa tomaranai ressha ni tobinoru yō na mono da.","zh":"成为职业棋士，就像跳上一列不会停下的火车。","level":"N2","point":"「～ということは」把前面一整句变成话题，“所谓……这件事”；「～ようなものだ」＝“就好比……”，用来打比方。","example":"留学するということは、新しい人生を始めるようなものだ。（留学就好比开始一段新的人生。）","work":"3月のライオン","workZh":"三月的狮子","ep":"","speaker":"桐山零","chunks":["プロになる","ということは","止まらない列車に","飛び乗る","ようなものだ。"],"verify":true,"id":174},{"jp":"焦りこそ最大のトラップだぜ？","ruby":"<ruby>焦<rt>あせ</rt></ruby>りこそ<ruby>最大<rt>さいだい</rt></ruby>のトラップだぜ？","romaji":"Aseri koso saidai no torappu da ze?","zh":"焦躁才是最大的陷阱哦？","level":"N3","point":"「名词＋こそ」强调“正是……”，把重点落在前面的词上；「だぜ」是男性的随意口语，平时说「だよ」就好。","example":"今年こそ合格したい。（今年一定要考过。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"松田陣平","chunks":["焦りこそ","最大の","トラップだぜ？"],"verify":true,"id":175},{"jp":"ようやく守らなければならないものができたんだ。君だ","ruby":"ようやく<ruby>守<rt>まも</rt></ruby>らなければならないものができたんだ。<ruby>君<rt>きみ</rt></ruby>だ","romaji":"Yōyaku mamoranakereba naranai mono ga dekita n da. Kimi da.","zh":"我终于有了必须守护的东西。就是你。","level":"N3","point":"「～なければならない」＝“必须……”；「ようやく」＝“好不容易、终于”，带有“等了很久”的感觉。","example":"明日までにレポートを出さなければならない。（明天之前必须交报告。）","work":"ハウルの動く城","workZh":"哈尔的移动城堡","ep":"劇場版","speaker":"ハウル","chunks":["ようやく","守らなければ","ならないものが","できたんだ。","君だ"],"verify":true,"id":176},{"jp":"理想を語れなくなったら人間の進化は止まるぞ","ruby":"<ruby>理想<rt>りそう</rt></ruby>を<ruby>語<rt>かた</rt></ruby>れなくなったら<ruby>人間<rt>にんげん</rt></ruby>の<ruby>進化<rt>しんか</rt></ruby>は<ruby>止<rt>と</rt></ruby>まるぞ","romaji":"Risō o katarenaku nattara ningen no shinka wa tomaru zo.","zh":"要是连理想都说不出口了，人类的进化就会停止。","level":"N3","point":"「可能形否定＋なくなる」＝“变得不能……了”，「語れなくなったら」就是“一旦再也谈不了理想”。","example":"年を取って、夜更かしできなくなった。（上了年纪，熬不了夜了。）","work":"鋼の錬金術師","workZh":"钢之炼金术师","ep":"","speaker":"ロイ・マスタング","chunks":["理想を","語れなくなったら","人間の進化は","止まるぞ"],"verify":true,"id":177},{"jp":"君が未来で一人ぼっちにならないようにするためかな","ruby":"<ruby>君<rt>きみ</rt></ruby>が<ruby>未来<rt>みらい</rt></ruby>で<ruby>一人<rt>ひとり</rt></ruby>ぼっちにならないようにするためかな","romaji":"Kimi ga mirai de hitoribocchi ni naranai yō ni suru tame ka na.","zh":"大概是为了让你在未来不会孤单一人吧。","level":"N3","point":"「～ないようにする」＝“设法不让……”；「～ため」表示目的；句尾「かな」是自言自语式的“……吧”。","example":"忘れないように、メモしておく。（为了不忘记，先记下来。）","work":"葬送のフリーレン","workZh":"葬送的芙莉莲","ep":"第7話","speaker":"ヒンメル","chunks":["君が未来で","一人ぼっちに","ならないように","するためかな"],"verify":true,"id":178},{"jp":"弾ける機会と聴いてくれる人がいるなら、私は全力で弾く。","ruby":"<ruby>弾<rt>ひ</rt></ruby>ける<ruby>機会<rt>きかい</rt></ruby>と<ruby>聴<rt>き</rt></ruby>いてくれる<ruby>人<rt>ひと</rt></ruby>がいるなら、<ruby>私<rt>わたし</rt></ruby>は<ruby>全力<rt>ぜんりょく</rt></ruby>で<ruby>弾<rt>ひ</rt></ruby>く。","romaji":"Hikeru kikai to kiite kureru hito ga iru nara, watashi wa zenryoku de hiku.","zh":"只要有演奏的机会和愿意听的人，我就会全力去弹。","level":"N3","point":"「～なら」表示假定条件，“如果……的话”；「～てくれる」表示别人为自己做某事，带感激之情。","example":"手伝ってくれる人がいるなら、引っ越しは一日で終わる。（要是有人帮忙，一天就能搬完家。）","work":"四月は君の嘘","workZh":"四月是你的谎言","ep":"","speaker":"宮園かをり","chunks":["弾ける機会と","聴いてくれる人が","いるなら、","私は全力で弾く。"],"verify":true,"id":179},{"jp":"我々は孤独だ。だが一人ではない","ruby":"<ruby>我々<rt>われわれ</rt></ruby>は<ruby>孤独<rt>こどく</rt></ruby>だ。だが<ruby>一人<rt>ひとり</rt></ruby>ではない","romaji":"Wareware wa kodoku da. Daga hitori de wa nai.","zh":"我们是孤独的。但我们并不是一个人。","level":"N3","point":"「だが」是偏书面、偏硬的“但是”，比「でも」「けど」正式；「我々」是“我们”的正式说法，演讲里常用。","example":"失敗は多かった。だが、後悔はしていない。（失败很多，但我不后悔。）","work":"宇宙兄弟","workZh":"宇宙兄弟","ep":"","speaker":"エディ・J","chunks":["我々は","孤独だ。","だが","一人ではない"],"verify":true,"id":180},{"jp":"悩むならなってから悩みなさい","ruby":"<ruby>悩<rt>なや</rt></ruby>むならなってから<ruby>悩<rt>なや</rt></ruby>みなさい","romaji":"Nayamu nara natte kara nayaminasai.","zh":"要烦恼的话，等真当上了再烦恼吧。","level":"N3","point":"「～てから」＝“……之后再……”；「～なさい」是温和的命令，长辈对晚辈、老师对学生常用。","example":"手を洗ってから食べなさい。（洗了手再吃。）","work":"宇宙兄弟","workZh":"宇宙兄弟","ep":"","speaker":"金子シャロン","chunks":["悩むなら","なってから","悩みなさい"],"verify":true,"id":181},{"jp":"国が滅びたのに王だけ生きているなんて滑稽だわ","ruby":"<ruby>国<rt>くに</rt></ruby>が<ruby>滅<rt>ほろ</rt></ruby>びたのに<ruby>王<rt>おう</rt></ruby>だけ<ruby>生<rt>い</rt></ruby>きているなんて<ruby>滑稽<rt>こっけい</rt></ruby>だわ","romaji":"Kuni ga horobita noni ō dake ikite iru nante kokkei da wa.","zh":"国家都灭亡了，只有国王还活着，真是可笑。","level":"N3","point":"「～なんて」表示意外、轻视或批评，“竟然……”；「～のに」是带不满的逆接，“明明……却……”。","example":"こんな簡単な問題を間違えるなんて、信じられない。（竟然做错这么简单的题，难以置信。）","work":"天空の城ラピュタ","workZh":"天空之城","ep":"劇場版","speaker":"シータ","chunks":["国が滅びたのに","王だけ","生きているなんて","滑稽だわ"],"verify":true,"id":182},{"jp":"惚れた女にゃ幸せになってほしいだけだ","ruby":"<ruby>惚<rt>ほ</rt></ruby>れた<ruby>女<rt>おんな</rt></ruby>にゃ<ruby>幸<rt>しあわ</rt></ruby>せになってほしいだけだ","romaji":"Horeta onna nya shiawase ni natte hoshii dake da.","zh":"我只是希望我爱上的女人能幸福而已。","level":"N3","point":"「～てほしい」＝“希望（别人）……”；「にゃ」是「には」的口语缩约，比较粗犷，平时说「には」。","example":"母には長生きしてほしい。（希望妈妈长寿。）","work":"銀魂","workZh":"银魂","ep":"","speaker":"土方十四郎","chunks":["惚れた女にゃ","幸せに","なってほしい","だけだ"],"verify":true,"id":183},{"jp":"だます方が悪いに決まっている","ruby":"だます<ruby>方<rt>ほう</rt></ruby>が<ruby>悪<rt>わる</rt></ruby>いに<ruby>決<rt>き</rt></ruby>まっている","romaji":"Damasu hō ga warui ni kimatte iru.","zh":"当然是骗人的一方不对。","level":"N3","point":"「～に決まっている」＝“肯定……、当然……”，说话人非常确信，口语常说「～に決まってる」。","example":"そんなの嘘に決まってるよ。（那肯定是骗人的。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"クラピカ","chunks":["だます方が","悪いに","決まっている"],"verify":true,"id":184},{"jp":"友達になるのにだって資格なんていらない！！","ruby":"<ruby>友達<rt>ともだち</rt></ruby>になるのにだって<ruby>資格<rt>しかく</rt></ruby>なんていらない！！","romaji":"Tomodachi ni naru no ni datte shikaku nante iranai!!","zh":"交朋友根本不需要什么资格！！","level":"N3","point":"「～のに」在这里表示目的或用途，“做……时”，常接「いる」「必要」「使う」；「だって」＝“就连……也”；「なんて」带轻视语气。","example":"この辞書は日本語を勉強するのに役立つ。（这本词典对学日语很有用。）","work":"HUNTER×HUNTER","workZh":"全职猎人","ep":"","speaker":"ゴン","chunks":["友達になるのにだって","資格なんて","いらない！！"],"verify":true,"id":185},{"jp":"言葉は刃物なんだ。使い方を間違えると厄介な凶器になる……","ruby":"<ruby>言葉<rt>ことば</rt></ruby>は<ruby>刃物<rt>はもの</rt></ruby>なんだ。<ruby>使<rt>つか</rt></ruby>い<ruby>方<rt>かた</rt></ruby>を<ruby>間違<rt>まちが</rt></ruby>えると<ruby>厄介<rt>やっかい</rt></ruby>な<ruby>凶器<rt>きょうき</rt></ruby>になる……","romaji":"Kotoba wa hamono nan da. Tsukaikata o machigaeru to yakkai na kyōki ni naru...","zh":"语言就是刀。用错了方法，就会变成可怕的凶器……","level":"N3","point":"「～と」表示“一……就会……”的必然结果；「名词＋なんだ」用来解释、强调自己的看法。","example":"このボタンを押すと、ドアが開く。（一按这个按钮，门就会打开。）","work":"名探偵コナン","workZh":"名侦探柯南","ep":"","speaker":"江戸川コナン","chunks":["言葉は刃物なんだ。","使い方を","間違えると","厄介な凶器に","なる……"],"verify":true,"id":186},{"jp":"…長い間！！くそお世話になりました！！","ruby":"…<ruby>長<rt>なが</rt></ruby>い<ruby>間<rt>あいだ</rt></ruby>！！くそお<ruby>世話<rt>せわ</rt></ruby>になりました！！","romaji":"...Nagai aida!! Kuso osewa ni narimashita!!","zh":"……这么多年来！！承蒙您他妈的照顾了！！","level":"N3","point":"「お世話になりました」是向照顾过自己的人道谢的固定敬语，离职、毕业、搬家时常用。「くそ」本是粗话，这里是山治不会表达感情的反差，日常千万别加。","example":"三年間、大変お世話になりました。（这三年承蒙您多方关照。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"サンジ","chunks":["…長い間！！","くそ","お世話に","なりました！！"],"verify":true,"id":187},{"jp":"奇跡は諦めない奴の頭上にしか降りてこない！！","ruby":"<ruby>奇跡<rt>きせき</rt></ruby>は<ruby>諦<rt>あきら</rt></ruby>めない<ruby>奴<rt>やつ</rt></ruby>の<ruby>頭上<rt>ずじょう</rt></ruby>にしか<ruby>降<rt>お</rt></ruby>りてこない！！","romaji":"Kiseki wa akiramenai yatsu no zujō ni shika orite konai!!","zh":"奇迹只会降临在不放弃的人头上！！","level":"N3","point":"「～しか～ない」＝“只……”，用否定形式表达限定；「奴」比较粗，平时说「人」更合适。","example":"財布に百円しか残っていない。（钱包里只剩一百日元了。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"イワンコフ","chunks":["奇跡は","諦めない奴の","頭上にしか","降りてこない！！"],"verify":true,"id":188},{"jp":"いつかきっと返しに来い立派な海賊になってな","ruby":"いつかきっと<ruby>返<rt>かえ</rt></ruby>しに<ruby>来<rt>こ</rt></ruby>い<ruby>立派<rt>りっぱ</rt></ruby>な<ruby>海賊<rt>かいぞく</rt></ruby>になってな","romaji":"Itsuka kitto kaeshi ni koi rippa na kaizoku ni natte na.","zh":"总有一天一定要来还给我，等你成了出色的海贼的时候。","level":"N3","point":"「动词ます形＋に来る」表示来的目的，“来做……”；「来い」是「来る」的命令形；后半句是倒装，补充条件。","example":"明日、借りた本を返しに来ます。（明天来还借的书。）","work":"ONE PIECE","workZh":"航海王（海贼王）","ep":"","speaker":"シャンクス","chunks":["いつかきっと","返しに来い","立派な海賊に","なってな"],"verify":true,"id":189},{"jp":"いいの、どうせ人間なんてみんなちょっとずつどっかおかしいんだから","ruby":"いいの、どうせ<ruby>人間<rt>にんげん</rt></ruby>なんてみんなちょっとずつどっかおかしいんだから","romaji":"Ii no, dōse ningen nante minna chotto zutsu dokka okashii n dakara.","zh":"没关系，反正人嘛，每个人多少都有点不正常的地方。","level":"N3","point":"「どうせ」＝“反正、横竖”，带点自嘲或看开的语气；句尾「～んだから」表示理由，有“你就别在意了”的劝说口吻。","example":"どうせ間に合わないんだから、ゆっくり行こう。（反正也赶不上了，慢慢走吧。）","work":"言の葉の庭","workZh":"言叶之庭","ep":"劇場版","speaker":"雪野百香里","chunks":["いいの、","どうせ人間なんて","みんなちょっとずつ","どっかおかしいんだから"],"verify":true,"id":190},{"jp":"私は私に出来ることをするだけです","ruby":"<ruby>私<rt>わたし</rt></ruby>は<ruby>私<rt>わたし</rt></ruby>に<ruby>出来<rt>でき</rt></ruby>ることをするだけです","romaji":"Watashi wa watashi ni dekiru koto o suru dake desu.","zh":"我只是做我能做的事而已。","level":"N3","point":"「～だけだ」＝“只是……而已”；「私に出来る」里用「に」标出能力的主体。","example":"私は自分の仕事をするだけです。（我只是做好自己的工作。）","work":"薬屋のひとりごと","workZh":"药屋少女的呢喃","ep":"","speaker":"羅門","chunks":["私は","私に出来ることを","するだけです"],"verify":true,"id":191},{"jp":"“青春全部かけたって強くなれない”？まつげくん。懸けてから言いなさい","ruby":"“<ruby>青春<rt>せいしゅん</rt></ruby><ruby>全部<rt>ぜんぶ</rt></ruby>かけたって<ruby>強<rt>つよ</rt></ruby>くなれない”？まつげくん。<ruby>懸<rt>か</rt></ruby>けてから<ruby>言<rt>い</rt></ruby>いなさい","romaji":"\"Seishun zenbu kaketatte tsuyoku narenai\"? Matsuge-kun. Kakete kara iinasai.","zh":"“就算赌上全部青春也变不强”？睫毛君，等你真赌上了再说。","level":"N3","point":"「～たって」是「～ても」的口语，“就算……也……”；「～てから」＝“……之后再……”。","example":"今から走ったって、もう間に合わないよ。（就算现在跑也来不及了。）","work":"ちはやふる","workZh":"花牌情缘","ep":"","speaker":"原田秀雄","chunks":["“青春全部かけたって","強くなれない”？","まつげくん。","懸けてから言いなさい"],"verify":true,"id":192},{"jp":"一人じゃどうにもならなくなったら誰かに頼れ。","ruby":"<ruby>一人<rt>ひとり</rt></ruby>じゃどうにもならなくなったら<ruby>誰<rt>だれ</rt></ruby>かに<ruby>頼<rt>たよ</rt></ruby>れ。","romaji":"Hitori ja dō ni mo naranaku nattara dareka ni tayore.","zh":"一个人实在没办法的时候，就去依靠别人。","level":"N3","point":"「どうにもならない」＝“怎么也没办法”；「～じゃ」是「では」的口语；「頼れ」是「頼る」的命令形。","example":"一人じゃどうにもならないから、手伝ってくれない？（一个人实在搞不定，能帮我一下吗？）","work":"3月のライオン","workZh":"三月的狮子","ep":"","speaker":"林田高志","chunks":["一人じゃ","どうにもならなく","なったら","誰かに頼れ。"],"verify":true,"id":193},{"jp":"人は情熱を失うとせっかちになる","ruby":"<ruby>人<rt>ひと</rt></ruby>は<ruby>情熱<rt>じょうねつ</rt></ruby>を<ruby>失<rt>うしな</rt></ruby>うとせっかちになる","romaji":"Hito wa jōnetsu o ushinau to sekkachi ni naru.","zh":"人一旦失去热情，就会变得急躁。","level":"N3","point":"「～と」在这里表示一般规律，“一……就会……”；「せっかち」＝“性子急、急躁”，是很常用的形容动词。","example":"春になると、桜が咲く。（一到春天，樱花就开。）","work":"3月のライオン","workZh":"三月的狮子","ep":"","speaker":"野火止あづさ","chunks":["人は","情熱を失うと","せっかちになる"],"verify":true,"id":194}];
